INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-1', 'multiple-choice', 'easy',
  'Who is considered the ''Father of Delta Blues''?', 'Hvem regnes som ''Delta Blues-ens far''?', 'Vem anses vara ''Delta Blues fader''?', 'Wer gilt als ''Vater des Delta Blues''?', 'Kogo uważa się za ''Ojca Delta Blues''?',
  '["Robert Johnson","Charley Patton","Muddy Waters","B.B. King"]', '["Robert Johnson","Charley Patton","Muddy Waters","B.B. King"]', '["Robert Johnson","Charley Patton","Muddy Waters","B.B. King"]', '["Robert Johnson","Charley Patton","Muddy Waters","B.B. King"]', '["Robert Johnson","Charley Patton","Muddy Waters","B.B. King"]',
  1,
  'Charley Patton (ca. 1891–1934) is widely regarded as the ''Father of Delta Blues.'' Born in Edwards, Mississippi, he was the dominant figure at Dockery Plantation and directly influenced Son House, Robert Johnson, and Howlin'' Wolf. His raw, rhythmic guitar style and showmanship defined what Delta blues would become.', 'Charley Patton (ca. 1891–1934) regnes som ''Delta Blues-ens far.'' Født i Edwards, Mississippi, var han den dominerende skikkelsen på Dockery Plantation og påvirket direkte Son House, Robert Johnson og Howlin'' Wolf. Hans rå, rytmiske gitarstil og showmanship definerte hva Delta blues skulle bli.', 'Charley Patton (ca. 1891–1934) betraktas allmänt som ''Delta Blues fader.'' Född i Edwards, Mississippi, var han den dominerande gestalten på Dockery Plantation och påverkade direkt Son House, Robert Johnson och Howlin'' Wolf. Hans råa, rytmiska gitarrstil och showmanship definierade vad Delta blues skulle bli.', 'Charley Patton (ca. 1891–1934) gilt weithin als ''Vater des Delta Blues.'' Geboren in Edwards, Mississippi, war er die dominierende Figur auf der Dockery Plantation und beeinflusste direkt Son House, Robert Johnson und Howlin'' Wolf. Sein roher, rhythmischer Gitarrenstil und seine Bühnenpräsenz definierten, was Delta Blues werden sollte.', 'Charley Patton (ok. 1891–1934) jest powszechnie uważany za ''Ojca Delta Blues.'' Urodzony w Edwards w stanie Mississippi, był dominującą postacią na plantacji Dockery i bezpośrednio wpłynął na Son House''a, Roberta Johnsona i Howlin'' Wolfa. Jego surowy, rytmiczny styl gry na gitarze i sceniczna charyzma zdefiniowały to, czym miał stać się Delta blues.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-4', 'multiple-choice', 'easy',
  'Which technique is most typical of Delta blues guitar?', 'Hvilken teknikk er mest typisk for Delta blues-gitar?', 'Vilken teknik är mest typisk för Delta blues-gitarr?', 'Welche Technik ist am typischsten für Delta-Blues-Gitarre?', 'Jaka technika jest najbardziej typowa dla gitary w stylu Delta blues?',
  '["Fingerstyle and slide","Flatpicking","Tapping","Sweep picking"]', '["Fingerspill og slide","Flatpicking","Tapping","Sweep picking"]', '["Fingerspel och slide","Flatpicking","Tapping","Sweep picking"]', '["Fingerpicking und Slide","Flatpicking","Tapping","Sweep Picking"]', '["Gra palcami i slide","Flatpicking","Tapping","Sweep picking"]',
  0,
  'Delta blues is characterized by fingerstyle technique and the use of slide (bottleneck) on the guitar. Son House, Robert Johnson, and Charley Patton all used these techniques. The slide was originally made from a broken bottle neck or a knife blade, creating the haunting, vocal-like tones that define the genre.', 'Delta blues kjennetegnes av fingerspillteknikk og bruk av slide (flaskehals) på gitaren. Son House, Robert Johnson og Charley Patton brukte alle disse teknikkene. Sliden var opprinnelig laget av en knekt flaskehals eller et knivblad, og skapte de stemningsfulle, vokal-lignende tonene som definerer sjangeren.', 'Delta blues kännetecknas av fingerspelsteknik och användning av slide (bottleneck) på gitarren. Son House, Robert Johnson och Charley Patton använde alla dessa tekniker. Sliden gjordes ursprungligen av en avbruten flaskhals eller ett knivblad, vilket skapade de själfulla, röstlika tonerna som definierar genren.', 'Delta Blues zeichnet sich durch Fingerpicking-Technik und den Einsatz von Slide (Flaschenhals) auf der Gitarre aus. Son House, Robert Johnson und Charley Patton nutzten alle diese Techniken. Der Slide wurde ursprünglich aus einem abgebrochenen Flaschenhals oder einer Messerklinge hergestellt und erzeugte die eindringlichen, gesangsähnlichen Töne, die das Genre definieren.', 'Delta blues charakteryzuje się techniką gry palcami oraz użyciem slide''a (szyjki butelki) na gitarze. Son House, Robert Johnson i Charley Patton wszyscy stosowali te techniki. Slide był pierwotnie wykonany z odłamanej szyjki butelki lub ostrza noża, tworząc niepokojące, przypominające głos dźwięki, które definiują ten gatunek.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-5', 'multiple-choice', 'easy',
  'Which city is Chicago blues most associated with?', 'Hvilken by er Chicago blues mest assosiert med?', 'Vilken stad förknippas mest med Chicago blues?', 'Mit welcher Stadt wird Chicago Blues am meisten assoziiert?', 'Z jakim miastem najbardziej kojarzy się Chicago blues?',
  '["Memphis","Chicago","New Orleans","Clarksdale"]', '["Memphis","Chicago","New Orleans","Clarksdale"]', '["Memphis","Chicago","New Orleans","Clarksdale"]', '["Memphis","Chicago","New Orleans","Clarksdale"]', '["Memphis","Chicago","Nowy Orlean","Clarksdale"]',
  1,
  'Chicago blues developed when Delta blues artists like Muddy Waters, Howlin'' Wolf, and Little Walter migrated north during the Great Migration (1940s–50s). They electrified the acoustic Delta sound at legendary venues on the South Side, and Chess Records at 2120 South Michigan Avenue became the epicenter of this revolution.', 'Chicago blues utviklet seg da Delta blues-artister som Muddy Waters, Howlin'' Wolf og Little Walter migrerte nordover under Den store migrasjonen (1940–50-tallet). De elektrifiserte den akustiske Delta-lyden på legendariske spillesteder på South Side, og Chess Records på 2120 South Michigan Avenue ble episenteret for denne revolusjonen.', 'Chicago blues utvecklades när Delta blues-artister som Muddy Waters, Howlin'' Wolf och Little Walter migrerade norrut under Den stora migrationen (1940–50-talet). De elektrifierade det akustiska Delta-soundet på legendariska spelställen på South Side, och Chess Records på 2120 South Michigan Avenue blev epicentrumet för denna revolution.', 'Chicago Blues entwickelte sich, als Delta-Blues-Künstler wie Muddy Waters, Howlin'' Wolf und Little Walter während der Great Migration (1940er–50er) nach Norden zogen. Sie elektrifizierten den akustischen Delta-Sound in legendären Lokalen auf der South Side, und Chess Records in der 2120 South Michigan Avenue wurde zum Epizentrum dieser Revolution.', 'Chicago blues rozwinął się, gdy artyści delta bluesa, tacy jak Muddy Waters, Howlin'' Wolf i Little Walter, migrowali na północ podczas Wielkiej Migracji (lata 40.–50. XX wieku). Zelektryfikowali akustyczne brzmienie Delty w legendarnych lokalach na South Side, a Chess Records przy 2120 South Michigan Avenue stało się epicentrum tej rewolucji.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-10', 'multiple-choice', 'easy',
  'Who was known as ''The Queen of the Blues''?', 'Hvem var kjent som ''Bluesens dronning''?', 'Vem var känd som ''Bluesens drottning''?', 'Wer war bekannt als ''Die Königin des Blues''?', 'Kto był znany jako ''Królowa Bluesa''?',
  '["Bessie Smith","Ma Rainey","Koko Taylor","Etta James"]', '["Bessie Smith","Ma Rainey","Koko Taylor","Etta James"]', '["Bessie Smith","Ma Rainey","Koko Taylor","Etta James"]', '["Bessie Smith","Ma Rainey","Koko Taylor","Etta James"]', '["Bessie Smith","Ma Rainey","Koko Taylor","Etta James"]',
  2,
  'Koko Taylor (1928–2009), born Cora Anna Walton in Shelby County, Tennessee, earned the title ''Queen of the Blues'' through her powerhouse vocals and domination of the Chicago blues scene. Her 1966 hit ''Wang Dang Doodle'' (written by Willie Dixon) sold over a million copies and became her signature song.', 'Koko Taylor (1928–2009), født Cora Anna Walton i Shelby County, Tennessee, fikk tittelen ''Bluesens dronning'' gjennom sin kraftfulle vokal og dominans på Chicago blues-scenen. Hennes hit ''Wang Dang Doodle'' fra 1966 (skrevet av Willie Dixon) solgte over en million eksemplarer og ble hennes signaturlåt.', 'Koko Taylor (1928–2009), född Cora Anna Walton i Shelby County, Tennessee, förtjänade titeln ''Bluesens drottning'' genom sin kraftfulla sång och dominans på Chicago blues-scenen. Hennes hit ''Wang Dang Doodle'' från 1966 (skriven av Willie Dixon) sålde över en miljon exemplar och blev hennes signaturlåt.', 'Koko Taylor (1928–2009), geboren als Cora Anna Walton in Shelby County, Tennessee, erwarb sich den Titel ''Königin des Blues'' durch ihren kraftvollen Gesang und ihre Dominanz der Chicago-Blues-Szene. Ihr Hit ''Wang Dang Doodle'' von 1966 (geschrieben von Willie Dixon) verkaufte sich über eine Million Mal und wurde ihr Erkennungslied.', 'Koko Taylor (1928–2009), urodzona jako Cora Anna Walton w hrabstwie Shelby w stanie Tennessee, zdobyła tytuł ''Królowej Bluesa'' dzięki potężnemu wokalowi i dominacji na scenie chicagowskiego bluesa. Jej hit ''Wang Dang Doodle'' z 1966 roku (napisany przez Williego Dixona) sprzedał się w ponad milionie egzemplarzy i stał się jej sztandarową piosenką.',
  'koko-taylor', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-11', 'multiple-choice', 'easy',
  'Which instrument is Howlin'' Wolf most known for?', 'Hvilket instrument er Howlin'' Wolf mest kjent for?', 'Vilket instrument är Howlin'' Wolf mest känd för?', 'Für welches Instrument ist Howlin'' Wolf am bekanntesten?', 'Z jakiego instrumentu Howlin'' Wolf jest najbardziej znany?',
  '["Guitar","Harmonica","Vocals","Piano"]', '["Gitar","Munnspill","Vokal","Piano"]', '["Gitarr","Munspel","Sång","Piano"]', '["Gitarre","Mundharmonika","Gesang","Klavier"]', '["Gitara","Harmonijka ustna","Wokal","Fortepian"]',
  2,
  'Chester Arthur Burnett (1910–1976), known as Howlin'' Wolf, had one of the most powerful and recognizable voices in blues history. Standing 6''3" and weighing 275 lbs, his deep, growling voice was described by Sam Phillips as ''where the soul of man never dies.'' He also played harmonica, but it was his vocals that defined songs like ''Smokestack Lightning'' and ''Killing Floor.''', 'Chester Arthur Burnett (1910–1976), kjent som Howlin'' Wolf, hadde en av de kraftigste og mest gjenkjennelige stemmene i blueshistorien. 190 cm høy og 125 kg tung, ble hans dype, brummende stemme beskrevet av Sam Phillips som ''der menneskets sjel aldri dør.'' Han spilte også munnspill, men det var vokalen hans som definerte sanger som ''Smokestack Lightning'' og ''Killing Floor.''', 'Chester Arthur Burnett (1910–1976), känd som Howlin'' Wolf, hade en av de mäktigaste och mest igenkännbara rösterna i bluesens historia. 190 cm lång och 125 kg tung, beskrevs hans djupa, morrande röst av Sam Phillips som ''där människans själ aldrig dör.'' Han spelade även munspel, men det var sången som definierade låtar som ''Smokestack Lightning'' och ''Killing Floor.''', 'Chester Arthur Burnett (1910–1976), bekannt als Howlin'' Wolf, hatte eine der kraftvollsten und erkennbarsten Stimmen der Blues-Geschichte. Bei 1,90 m Größe und 125 kg Gewicht wurde seine tiefe, grollende Stimme von Sam Phillips als ''wo die Seele des Menschen niemals stirbt'' beschrieben. Er spielte auch Mundharmonika, aber es war sein Gesang, der Songs wie ''Smokestack Lightning'' und ''Killing Floor'' definierte.', 'Chester Arthur Burnett (1910–1976), znany jako Howlin'' Wolf, miał jeden z najpotężniejszych i najbardziej rozpoznawalnych głosów w historii bluesa. Mierząc 190 cm wzrostu i ważąc 125 kg, jego głęboki, warczący głos został opisany przez Sama Phillipsa jako ''miejsce, gdzie dusza człowieka nigdy nie umiera.'' Grał także na harmonijce, ale to jego wokal definiował takie utwory jak ''Smokestack Lightning'' i ''Killing Floor.''',
  'howlin-wolf', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-13', 'multiple-choice', 'easy',
  'Which guitarist named his guitar ''Lucille''?', 'Hvilken gitarist kalte gitaren sin ''Lucille''?', 'Vilken gitarrist kallade sin gitarr ''Lucille''?', 'Welcher Gitarrist nannte seine Gitarre ''Lucille''?', 'Który gitarzysta nazwał swoją gitarę ''Lucille''?',
  '["Muddy Waters","B.B. King","Albert King","Freddie King"]', '["Muddy Waters","B.B. King","Albert King","Freddie King"]', '["Muddy Waters","B.B. King","Albert King","Freddie King"]', '["Muddy Waters","B.B. King","Albert King","Freddie King"]', '["Muddy Waters","B.B. King","Albert King","Freddie King"]',
  1,
  'Riley B. King (1925–2015), known as B.B. King, named all his guitars ''Lucille'' after a near-fatal incident in Twist, Arkansas in 1949. Two men fighting over a woman named Lucille knocked over a kerosene barrel, setting the dance hall on fire. B.B. ran back inside to save his $30 Gibson guitar, and named it Lucille as a reminder to never do anything so foolish again.', 'Riley B. King (1925–2015), kjent som B.B. King, kalte alle gitarene sine ''Lucille'' etter en nær-dødelig hendelse i Twist, Arkansas i 1949. To menn som sloss om en kvinne ved navn Lucille veltet en kerosenfat og satte danselokalet i brann. B.B. løp tilbake inn for å redde sin Gibson-gitar til $30, og kalte den Lucille som en påminnelse om aldri å gjøre noe så dumt igjen.', 'Riley B. King (1925–2015), känd som B.B. King, kallade alla sina gitarrer ''Lucille'' efter en nästan dödlig incident i Twist, Arkansas 1949. Två män som slogs om en kvinna vid namn Lucille välte en fotogentunna och satte dansstället i brand. B.B. sprang tillbaka in för att rädda sin Gibson-gitarr värd $30, och kallade den Lucille som en påminnelse om att aldrig göra något så dumdristigt igen.', 'Riley B. King (1925–2015), bekannt als B.B. King, nannte alle seine Gitarren ''Lucille'' nach einem beinahe tödlichen Vorfall in Twist, Arkansas im Jahr 1949. Zwei Männer, die sich um eine Frau namens Lucille stritten, stießen ein Kerosinfass um und setzten die Tanzhalle in Brand. B.B. rannte zurück hinein, um seine 30-Dollar-Gibson-Gitarre zu retten, und nannte sie Lucille als Erinnerung, nie wieder etwas so Dummes zu tun.', 'Riley B. King (1925–2015), znany jako B.B. King, nazwał wszystkie swoje gitary ''Lucille'' po niemal tragicznym incydencie w Twist w Arkansas w 1949 roku. Dwóch mężczyzn walczących o kobietę o imieniu Lucille przewróciło beczkę z naftą, podpalając salę taneczną. B.B. wbiegł z powrotem do środka, by uratować swoją gitarę Gibson wartą 30 dolarów, i nazwał ją Lucille jako przypomnienie, by nigdy więcej nie zrobić niczego tak głupiego.',
  'bb-king', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-14', 'multiple-choice', 'easy',
  'What does ''12-bar blues'' mean?', 'Hva betyr ''12-takters blues''?', 'Vad betyder ''12-takters blues''?', 'Was bedeutet ''12-Takt-Blues''?', 'Co oznacza ''12-taktowy blues''?',
  '["A blues with 12 verses","A chord progression over 12 bars","Blues played on a 12-string guitar","A blues lasting 12 minutes"]', '["En blues med 12 vers","En akkordprogresjon over 12 takter","Blues spilt på 12-strengs gitar","En blues som varer 12 minutter"]', '["En blues med 12 verser","En ackordprogression över 12 takter","Blues spelad på 12-strängad gitarr","En blues som varar 12 minuter"]', '["Ein Blues mit 12 Strophen","Eine Akkordfolge über 12 Takte","Blues auf einer 12-saitigen Gitarre gespielt","Ein Blues, der 12 Minuten dauert"]', '["Blues z 12 zwrotkami","Progresja akordów na 12 taktów","Blues grany na 12-strunowej gitarze","Blues trwający 12 minut"]',
  1,
  'The 12-bar blues is the backbone of blues music – a chord progression using I-IV-V chords that repeats over 12 bars. It follows a specific pattern: 4 bars of I, 2 bars of IV, 2 bars of I, then V-IV-I-I (or V). This structure has been used in thousands of blues, rock, and jazz songs from Robert Johnson to The Rolling Stones.', '12-takters blues er ryggraden i bluesmusikk – en akkordprogresjon med I-IV-V-akkorder som gjentas over 12 takter. Den følger et spesifikt mønster: 4 takter I, 2 takter IV, 2 takter I, deretter V-IV-I-I (eller V). Denne strukturen har blitt brukt i tusenvis av blues-, rock- og jazzsanger fra Robert Johnson til The Rolling Stones.', '12-takters blues är ryggraden i bluesmusik – en ackordprogression med I-IV-V-ackord som upprepas över 12 takter. Den följer ett specifikt mönster: 4 takter I, 2 takter IV, 2 takter I, sedan V-IV-I-I (eller V). Denna struktur har använts i tusentals blues-, rock- och jazzlåtar från Robert Johnson till The Rolling Stones.', 'Der 12-Takt-Blues ist das Rückgrat der Blues-Musik – eine Akkordfolge mit I-IV-V-Akkorden, die sich über 12 Takte wiederholt. Sie folgt einem bestimmten Muster: 4 Takte I, 2 Takte IV, 2 Takte I, dann V-IV-I-I (oder V). Diese Struktur wurde in Tausenden von Blues-, Rock- und Jazzsongs verwendet, von Robert Johnson bis zu den Rolling Stones.', '12-taktowy blues jest podstawą muzyki bluesowej – progresja akordów I-IV-V, która powtarza się przez 12 taktów. Podąża za konkretnym wzorem: 4 takty I, 2 takty IV, 2 takty I, następnie V-IV-I-I (lub V). Ta struktura była wykorzystywana w tysiącach utworów bluesowych, rockowych i jazzowych, od Roberta Johnsona po The Rolling Stones.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-15', 'multiple-choice', 'easy',
  'Who was known as ''Mother of the Blues''?', 'Hvem var kjent som ''Bluesens mor''?', 'Vem var känd som ''Bluesens moder''?', 'Wer war bekannt als ''Mutter des Blues''?', 'Kto był znany jako ''Matka Bluesa''?',
  '["Bessie Smith","Ma Rainey","Memphis Minnie","Victoria Spivey"]', '["Bessie Smith","Ma Rainey","Memphis Minnie","Victoria Spivey"]', '["Bessie Smith","Ma Rainey","Memphis Minnie","Victoria Spivey"]', '["Bessie Smith","Ma Rainey","Memphis Minnie","Victoria Spivey"]', '["Bessie Smith","Ma Rainey","Memphis Minnie","Victoria Spivey"]',
  1,
  'Gertrude ''Ma'' Rainey (1886–1939), born in Columbus, Georgia, is called ''Mother of the Blues'' because she was one of the earliest professional blues performers and the first generation to record. She mentored Bessie Smith and recorded over 100 songs for Paramount Records between 1923–1928, helping establish blues as a commercial genre.', 'Gertrude ''Ma'' Rainey (1886–1939), født i Columbus, Georgia, kalles ''Bluesens mor'' fordi hun var en av de tidligste profesjonelle bluesartistene og den første generasjonen som spilte inn. Hun veiledet Bessie Smith og spilte inn over 100 sanger for Paramount Records mellom 1923–1928, og hjalp til med å etablere blues som en kommersiell sjanger.', 'Gertrude ''Ma'' Rainey (1886–1939), född i Columbus, Georgia, kallas ''Bluesens moder'' eftersom hon var en av de tidigaste professionella bluesartisterna och den första generationen som spelade in. Hon var mentor åt Bessie Smith och spelade in över 100 låtar för Paramount Records mellan 1923–1928, vilket hjälpte till att etablera blues som en kommersiell genre.', 'Gertrude ''Ma'' Rainey (1886–1939), geboren in Columbus, Georgia, wird ''Mutter des Blues'' genannt, weil sie eine der frühesten professionellen Blues-Interpretinnen war und zur ersten Generation gehörte, die Aufnahmen machte. Sie war Mentorin von Bessie Smith und nahm zwischen 1923–1928 über 100 Songs für Paramount Records auf, wodurch sie half, Blues als kommerzielles Genre zu etablieren.', 'Gertrude ''Ma'' Rainey (1886–1939), urodzona w Columbus w stanie Georgia, nazywana jest ''Matką Bluesa'', ponieważ była jedną z pierwszych profesjonalnych wykonawczyń bluesa i należała do pierwszego pokolenia, które nagrywało płyty. Była mentorką Bessie Smith i nagrała ponad 100 piosenek dla Paramount Records w latach 1923–1928, pomagając ustanowić blues jako gatunek komercyjny.',
  'ma-rainey', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-17', 'multiple-choice', 'easy',
  'What is a ''bottleneck'' in blues context?', 'Hva er en ''bottleneck'' i blues-sammenheng?', 'Vad är en ''bottleneck'' i blueskontext?', 'Was ist ein ''Bottleneck'' im Blues-Kontext?', 'Czym jest ''bottleneck'' w kontekście bluesa?',
  '["A type of harmonica","A slide tool for guitar","A chord type","A singing style"]', '["En type munnspill","Et slideverktøy for gitar","En akkordtype","En sangteknikk"]', '["En typ av munspel","Ett slideverktyg för gitarr","En ackordtyp","En sångstil"]', '["Eine Art Mundharmonika","Ein Slide-Werkzeug für Gitarre","Ein Akkordtyp","Ein Gesangsstil"]', '["Rodzaj harmonijki ustnej","Narzędzie slide do gitary","Rodzaj akordu","Styl śpiewu"]',
  1,
  'A bottleneck is a glass or metal tube worn on the finger to slide along the guitar strings, creating the singing, moaning tones that define Delta blues. Originally, players like Son House and Robert Johnson used actual broken bottle necks. Today, artists like Knut Reiersrud and Erja Lyytinen keep this tradition alive in Scandinavia.', 'En bottleneck er et glass- eller metallrør som bæres på fingeren for å gli langs gitarstrengene, og skaper de syngende, klagende tonene som definerer Delta blues. Opprinnelig brukte spillere som Son House og Robert Johnson faktiske knekte flaskehalser. I dag holder artister som Knut Reiersrud og Erja Lyytinen denne tradisjonen i live i Skandinavia.', 'En bottleneck är ett glas- eller metallrör som bärs på fingret för att glida längs gitarrsträngarna, vilket skapar de sjungande, klagande tonerna som definierar Delta blues. Ursprungligen använde spelare som Son House och Robert Johnson faktiska avbrutna flaskhalsar. Idag håller artister som Knut Reiersrud och Erja Lyytinen denna tradition levande i Skandinavien.', 'Ein Bottleneck ist eine Glas- oder Metallröhre, die am Finger getragen wird, um über die Gitarrensaiten zu gleiten und die singenden, klagenden Töne zu erzeugen, die den Delta Blues definieren. Ursprünglich verwendeten Musiker wie Son House und Robert Johnson tatsächlich abgebrochene Flaschenhälse. Heute halten Künstler wie Knut Reiersrud und Erja Lyytinen diese Tradition in Skandinavien lebendig.', 'Bottleneck to szklana lub metalowa rurka noszona na palcu, używana do ślizgania się po strunach gitary, tworząc śpiewne, jęczące tony definiujące Delta blues. Pierwotnie muzycy tacy jak Son House i Robert Johnson używali prawdziwych odłamanych szyjek butelek. Dziś artyści tacy jak Knut Reiersrud i Erja Lyytinen podtrzymują tę tradycję w Skandynawii.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-25', 'multiple-choice', 'easy',
  'Which Gibson guitar model is most associated with blues-rock?', 'Hvilken Gibson-gitarmodell er mest assosiert med blues-rock?', 'Vilken Gibson-gitarrmodell är mest förknippad med blues-rock?', 'Welches Gibson-Gitarrenmodell wird am meisten mit Blues-Rock assoziiert?', 'Który model gitary Gibson jest najbardziej kojarzony z blues-rockiem?',
  '["Gibson SG","Gibson Les Paul","Gibson Flying V","Gibson Explorer"]', '["Gibson SG","Gibson Les Paul","Gibson Flying V","Gibson Explorer"]', '["Gibson SG","Gibson Les Paul","Gibson Flying V","Gibson Explorer"]', '["Gibson SG","Gibson Les Paul","Gibson Flying V","Gibson Explorer"]', '["Gibson SG","Gibson Les Paul","Gibson Flying V","Gibson Explorer"]',
  1,
  'The Gibson Les Paul, designed in collaboration with guitarist Les Paul in 1952, has been the guitar of choice for blues-rock legends. Eric Clapton used one on the legendary ''Beano'' album with John Mayall''s Bluesbreakers (1966), Peter Green''s Les Paul produced the iconic tone on ''Albatross'', and Joe Bonamassa owns over 500 guitars but keeps returning to his Les Pauls.', 'Gibson Les Paul, designet i samarbeid med gitaristen Les Paul i 1952, har vært foretrukket gitar for blues-rock-legender. Eric Clapton brukte en på det legendariske ''Beano''-albumet med John Mayalls Bluesbreakers (1966), Peter Greens Les Paul produserte den ikoniske tonen på ''Albatross'', og Joe Bonamassa eier over 500 gitarer men vender stadig tilbake til sine Les Pauler.', 'Gibson Les Paul, designad i samarbete med gitarristen Les Paul 1952, har varit förstahandsvalet för blues-rock-legender. Eric Clapton använde en på det legendariska ''Beano''-albumet med John Mayalls Bluesbreakers (1966), Peter Greens Les Paul producerade den ikoniska tonen på ''Albatross'', och Joe Bonamassa äger över 500 gitarrer men återvänder ständigt till sina Les Pauls.', 'Die Gibson Les Paul, entworfen in Zusammenarbeit mit dem Gitarristen Les Paul im Jahr 1952, war die bevorzugte Gitarre von Blues-Rock-Legenden. Eric Clapton benutzte eine auf dem legendären ''Beano''-Album mit John Mayalls Bluesbreakers (1966), Peter Greens Les Paul erzeugte den ikonischen Ton auf ''Albatross'', und Joe Bonamassa besitzt über 500 Gitarren, kehrt aber immer wieder zu seinen Les Pauls zurück.', 'Gibson Les Paul, zaprojektowana we współpracy z gitarzystą Lesem Paulem w 1952 roku, była ulubioną gitarą legend blues-rocka. Eric Clapton używał jej na legendarnym albumie ''Beano'' z John Mayall''s Bluesbreakers (1966), Les Paul Petera Greena wyprodukował kultowe brzmienie na ''Albatross'', a Joe Bonamassa posiada ponad 500 gitar, ale wciąż wraca do swoich Les Pauli.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-29', 'multiple-choice', 'easy',
  'What instrument is the National Resonator guitar known for?', 'Hva er National Resonator-gitaren kjent for?', 'Vad är National Resonator-gitarren känd för?', 'Wofür ist die National-Resonator-Gitarre bekannt?', 'Z czego znana jest gitara National Resonator?',
  '["Electric distortion","Metallic acoustic resonance for slide blues","12-string tuning","Nylon string classical sound"]', '["Elektrisk forvrengning","Metallisk akustisk resonans for slide blues","12-strengs stemming","Nylonstreng klassisk lyd"]', '["Elektrisk distorsion","Metallisk akustisk resonans för slide-blues","12-sträng stämning","Nylonsträng klassisk klang"]', '["Elektrische Verzerrung","Metallische akustische Resonanz für Slide-Blues","12-saitige Stimmung","Klassischer Nylonsaiten-Klang"]', '["Elektryczne zniekształcenie","Metaliczny akustyczny rezonans do slide bluesa","Strojenie 12-strunowe","Klasyczne brzmienie strun nylonowych"]',
  1,
  'The National Resonator guitar, first produced in 1927, uses spun aluminum cones instead of a wooden soundboard to produce a loud, metallic tone. Son House, Bukka White, and Tampa Red all played Nationals, and the instrument became synonymous with pre-war Delta and country blues. Today it remains iconic – you can see one on the cover of Dire Straits'' ''Brothers in Arms.''', 'National Resonator-gitaren, først produsert i 1927, bruker spunne aluminiumskjegler i stedet for et trelokk for å produsere en høy, metallisk tone. Son House, Bukka White og Tampa Red spilte alle Nationals, og instrumentet ble synonymt med førkrigs Delta og country blues. I dag er den fortsatt ikonisk – du kan se en på coveret til Dire Straits'' ''Brothers in Arms.''', 'National Resonator-gitarren, som först tillverkades 1927, använder spunna aluminiumkoner istället för ett trälock för att producera en hög, metallisk ton. Son House, Bukka White och Tampa Red spelade alla Nationals, och instrumentet blev synonymt med förkrigstidens Delta- och country blues. Idag är den fortfarande ikonisk – du kan se en på omslaget till Dire Straits'' ''Brothers in Arms.''', 'Die National-Resonator-Gitarre, erstmals 1927 hergestellt, verwendet gedrehte Aluminiumkegel anstelle eines Holzresonanzbodens, um einen lauten, metallischen Ton zu erzeugen. Son House, Bukka White und Tampa Red spielten alle Nationals, und das Instrument wurde zum Synonym für Vorkriegs-Delta- und Country-Blues. Heute ist sie noch immer ikonisch – man sieht eine auf dem Cover von Dire Straits'' ''Brothers in Arms.''', 'Gitara National Resonator, produkowana od 1927 roku, wykorzystuje wirowane aluminiowe stożki zamiast drewnianej płyty rezonansowej, aby wytworzyć głośny, metaliczny ton. Son House, Bukka White i Tampa Red grali na Nationalach, a instrument stał się synonimem przedwojennego Delta i country bluesa. Dziś pozostaje ikoniczny – można ją zobaczyć na okładce albumu Dire Straits ''Brothers in Arms.''',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-31', 'multiple-choice', 'easy',
  'What is the ''blue note'' in blues music?', 'Hva er ''blue note'' i bluesmusikk?', 'Vad är en ''blue note'' i bluesmusik?', 'Was ist die ''Blue Note'' in der Bluesmusik?', 'Czym jest ''blue note'' w muzyce bluesowej?',
  '["A famous jazz club in New York","A flattened 3rd, 5th, or 7th note in a scale","A type of harmonica reed","A record label"]', '["En berømt jazzklubb i New York","En senket 3., 5. eller 7. tone i en skala","En type munnspillblad","Et plateselskap"]', '["En berömd jazzklubb i New York","En sänkt 3:e, 5:e eller 7:e ton i en skala","En typ av munspelston","Ett skivbolag"]', '["Ein berühmter Jazzclub in New York","Eine erniedrigte 3., 5. oder 7. Note einer Tonleiter","Eine Art Mundharmonika-Zunge","Ein Plattenlabel"]', '["Słynny klub jazzowy w Nowym Jorku","Obniżony 3., 5. lub 7. dźwięk w skali","Rodzaj stroika harmonijki ustnej","Wytwórnia płytowa"]',
  1,
  'Blue notes are the flattened 3rd, 5th, or 7th notes in a major scale, creating the tension and emotional depth that defines blues. These notes trace their roots to West African musical scales and work songs. The ''Blue Note'' jazz club in New York and Blue Note Records were both named after this musical concept.', 'Blue notes er de senkede 3., 5. eller 7. tonene i en durskala, og skaper spenningen og den emosjonelle dybden som definerer blues. Disse tonene har sine røtter i vestafrikanske musikalske skalaer og arbeidssanger. ''Blue Note''-jazzklubben i New York og Blue Note Records ble begge oppkalt etter dette musikalske konseptet.', 'Blue notes är de sänkta 3:e, 5:e eller 7:e tonerna i en durskala, vilket skapar den spänning och emotionella djup som definierar blues. Dessa toner har sina rötter i västafrikanska musikaliska skalor och arbetssånger. Jazzklubben ''Blue Note'' i New York och Blue Note Records fick båda sina namn efter detta musikaliska koncept.', 'Blue Notes sind die erniedrigten 3., 5. oder 7. Noten einer Durtonleiter, die die Spannung und emotionale Tiefe erzeugen, die den Blues definieren. Diese Noten haben ihre Wurzeln in westafrikanischen Tonleitern und Arbeitsliedern. Sowohl der Jazzclub ''Blue Note'' in New York als auch Blue Note Records wurden nach diesem musikalischen Konzept benannt.', 'Blue notes to obniżone 3., 5. lub 7. dźwięki w skali durowej, tworzące napięcie i emocjonalną głębię definiującą blues. Te dźwięki wywodzą się z zachodnioafrykańskich skal muzycznych i pieśni roboczych. Klub jazzowy ''Blue Note'' w Nowym Jorku oraz wytwórnia Blue Note Records zostały nazwane na cześć tej koncepcji muzycznej.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-2', 'multiple-choice', 'medium',
  'Which song, credited to Willie Dixon, became Muddy Waters'' signature tune?', 'Hvilken sang, kreditert Willie Dixon, ble Muddy Waters'' signaturmelodi?', 'Vilken låt, krediterad Willie Dixon, blev Muddy Waters signaturlåt?', 'Welcher Song, geschrieben von Willie Dixon, wurde zu Muddy Waters'' Erkennungslied?', 'Który utwór, autorstwa Williego Dixona, stał się sztandarową piosenką Muddy''ego Watersa?',
  '["Cross Road Blues","Hoochie Coochie Man","Dust My Broom","Sweet Home Chicago"]', '["Cross Road Blues","Hoochie Coochie Man","Dust My Broom","Sweet Home Chicago"]', '["Cross Road Blues","Hoochie Coochie Man","Dust My Broom","Sweet Home Chicago"]', '["Cross Road Blues","Hoochie Coochie Man","Dust My Broom","Sweet Home Chicago"]', '["Cross Road Blues","Hoochie Coochie Man","Dust My Broom","Sweet Home Chicago"]',
  1,
  '''Hoochie Coochie Man'' was written by Willie Dixon and recorded by Muddy Waters at Chess Studios in January 1954. It reached #3 on the R&B charts and became one of the most covered songs in blues history. Dixon was the creative mastermind behind Chess Records, writing hits for Muddy, Howlin'' Wolf, Little Walter, and Koko Taylor.', '''Hoochie Coochie Man'' ble skrevet av Willie Dixon og spilt inn av Muddy Waters på Chess Studios i januar 1954. Den nådde 3. plass på R&B-listene og ble en av de mest covrede sangene i blueshistorien. Dixon var det kreative geniet bak Chess Records, og skrev hits for Muddy, Howlin'' Wolf, Little Walter og Koko Taylor.', '''Hoochie Coochie Man'' skrevs av Willie Dixon och spelades in av Muddy Waters på Chess Studios i januari 1954. Den nådde 3:e plats på R&B-listorna och blev en av de mest coverade låtarna i bluesens historia. Dixon var det kreativa geniet bakom Chess Records och skrev hits för Muddy, Howlin'' Wolf, Little Walter och Koko Taylor.', '''Hoochie Coochie Man'' wurde von Willie Dixon geschrieben und im Januar 1954 von Muddy Waters in den Chess Studios aufgenommen. Er erreichte Platz 3 der R&B-Charts und wurde zu einem der meistgecoverten Songs der Blues-Geschichte. Dixon war der kreative Kopf hinter Chess Records und schrieb Hits für Muddy, Howlin'' Wolf, Little Walter und Koko Taylor.', '''Hoochie Coochie Man'' został napisany przez Williego Dixona i nagrany przez Muddy''ego Watersa w Chess Studios w styczniu 1954 roku. Utwór dotarł do 3. miejsca list R&B i stał się jedną z najczęściej coverowanych piosenek w historii bluesa. Dixon był kreatywnym mózgiem stojącym za Chess Records, pisząc przeboje dla Muddy''ego, Howlin'' Wolfa, Little Waltera i Koko Taylor.',
  'muddy-waters', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-3', 'multiple-choice', 'medium',
  'Who played harmonica on ''Juke'' (1952)?', 'Hvem spilte munnspill på ''Juke'' (1952)?', 'Vem spelade munspel på ''Juke'' (1952)?', 'Wer spielte Mundharmonika auf ''Juke'' (1952)?', 'Kto grał na harmonijce ustnej w utworze ''Juke'' (1952)?',
  '["Sonny Boy Williamson","Little Walter","Big Walter Horton","Junior Wells"]', '["Sonny Boy Williamson","Little Walter","Big Walter Horton","Junior Wells"]', '["Sonny Boy Williamson","Little Walter","Big Walter Horton","Junior Wells"]', '["Sonny Boy Williamson","Little Walter","Big Walter Horton","Junior Wells"]', '["Sonny Boy Williamson","Little Walter","Big Walter Horton","Junior Wells"]',
  1,
  'Marion Walter Jacobs (1930–1968), known as Little Walter, recorded ''Juke'' in 1952 at Chess Studios. It became the first (and still one of the only) instrumental blues harmonica singles to reach #1 on the R&B charts, staying there for 8 weeks. He revolutionized the instrument by amplifying it through a microphone cupped in his hands, creating the distorted, powerful tone that became the standard for Chicago blues harmonica.', 'Marion Walter Jacobs (1930–1968), kjent som Little Walter, spilte inn ''Juke'' i 1952 på Chess Studios. Den ble den første (og fortsatt en av de eneste) instrumentale blues-munnspillsinglene som nådde førsteplass på R&B-listene, der den lå i 8 uker. Han revolusjonerte instrumentet ved å forsterke det gjennom en mikrofon holdt i hendene, og skapte den forvrengte, kraftfulle tonen som ble standarden for Chicago blues-munnspill.', 'Marion Walter Jacobs (1930–1968), känd som Little Walter, spelade in ''Juke'' 1952 på Chess Studios. Den blev den första (och fortfarande en av de enda) instrumentala blues-munspelssinglarna som nådde förstaplatsen på R&B-listorna, där den låg i 8 veckor. Han revolutionerade instrumentet genom att förstärka det via en mikrofon i sina kupade händer, vilket skapade den förvrängda, kraftfulla ton som blev standarden för Chicago blues-munspel.', 'Marion Walter Jacobs (1930–1968), bekannt als Little Walter, nahm ''Juke'' 1952 in den Chess Studios auf. Es wurde die erste (und immer noch eine der wenigen) instrumentale Blues-Mundharmonika-Single, die Platz 1 der R&B-Charts erreichte und dort 8 Wochen blieb. Er revolutionierte das Instrument, indem er es durch ein in den Händen gehaltenes Mikrofon verstärkte und so den verzerrten, kraftvollen Ton schuf, der zum Standard für Chicago-Blues-Mundharmonika wurde.', 'Marion Walter Jacobs (1930–1968), znany jako Little Walter, nagrał ''Juke'' w 1952 roku w Chess Studios. Stał się on pierwszym (i wciąż jednym z niewielu) instrumentalnym singlem bluesowym z harmonijką ustną, który dotarł na 1. miejsce list R&B, pozostając tam przez 8 tygodni. Zrewolucjonizował instrument, wzmacniając go przez mikrofon trzymany w dłoniach, tworząc zniekształcony, potężny ton, który stał się standardem chicagowskiej harmonijki bluesowej.',
  'little-walter', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-6', 'multiple-choice', 'medium',
  'Who wrote ''Cross Road Blues'' (1936)?', 'Hvem skrev ''Cross Road Blues'' (1936)?', 'Vem skrev ''Cross Road Blues'' (1936)?', 'Wer schrieb ''Cross Road Blues'' (1936)?', 'Kto napisał ''Cross Road Blues'' (1936)?',
  '["Son House","Robert Johnson","Skip James","Blind Lemon Jefferson"]', '["Son House","Robert Johnson","Skip James","Blind Lemon Jefferson"]', '["Son House","Robert Johnson","Skip James","Blind Lemon Jefferson"]', '["Son House","Robert Johnson","Skip James","Blind Lemon Jefferson"]', '["Son House","Robert Johnson","Skip James","Blind Lemon Jefferson"]',
  1,
  'Robert Johnson (1911–1938) wrote and recorded ''Cross Road Blues'' at the Gunter Hotel in San Antonio, Texas on November 27, 1936. The song, about standing at a crossroads trying to hitch a ride, later inspired the myth of Johnson selling his soul to the devil. Eric Clapton''s cover with Cream (''Crossroads'') in 1968 brought this Delta classic to a worldwide rock audience.', 'Robert Johnson (1911–1938) skrev og spilte inn ''Cross Road Blues'' på Gunter Hotel i San Antonio, Texas 27. november 1936. Sangen, om å stå ved et veikryss og prøve å haike, inspirerte senere myten om at Johnson solgte sjelen sin til djevelen. Eric Claptons cover med Cream (''Crossroads'') i 1968 brakte denne Delta-klassikeren til et verdensomspennende rockpublikum.', 'Robert Johnson (1911–1938) skrev och spelade in ''Cross Road Blues'' på Gunter Hotel i San Antonio, Texas den 27 november 1936. Låten, om att stå vid en vägkorsning och försöka lifta, inspirerade senare myten om att Johnson sålde sin själ till djävulen. Eric Claptons cover med Cream (''Crossroads'') 1968 förde denna Delta-klassiker till en global rockpublik.', 'Robert Johnson (1911–1938) schrieb und nahm ''Cross Road Blues'' am 27. November 1936 im Gunter Hotel in San Antonio, Texas, auf. Der Song, der davon handelt, an einer Kreuzung zu stehen und per Anhalter zu fahren, inspirierte später den Mythos, Johnson habe seine Seele an den Teufel verkauft. Eric Claptons Coverversion mit Cream (''Crossroads'') 1968 brachte diesen Delta-Klassiker einem weltweiten Rockpublikum nahe.', 'Robert Johnson (1911–1938) napisał i nagrał ''Cross Road Blues'' w hotelu Gunter w San Antonio w Teksasie 27 listopada 1936 roku. Piosenka, opowiadająca o staniu na rozstaju dróg i próbie złapania okazji, zainspirowała później mit o tym, że Johnson sprzedał duszę diabłu. Cover Erica Claptona z zespołem Cream (''Crossroads'') z 1968 roku przybliżył tę klasykę Delty publiczności rockowej na całym świecie.',
  'robert-johnson', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-7', 'multiple-choice', 'medium',
  'Which record label was central to Chicago blues in the 1950s?', 'Hvilket plateselskap var sentralt for Chicago blues på 1950-tallet?', 'Vilket skivbolag var centralt för Chicago blues på 1950-talet?', 'Welches Plattenlabel war zentral für Chicago Blues in den 1950er-Jahren?', 'Która wytwórnia płytowa była kluczowa dla chicagowskiego bluesa w latach 50.?',
  '["Sun Records","Chess Records","Vee-Jay","Motown"]', '["Sun Records","Chess Records","Vee-Jay","Motown"]', '["Sun Records","Chess Records","Vee-Jay","Motown"]', '["Sun Records","Chess Records","Vee-Jay","Motown"]', '["Sun Records","Chess Records","Vee-Jay","Motown"]',
  1,
  'Chess Records, founded by Polish-American brothers Leonard and Phil Chess in 1950, was headquartered at 2120 South Michigan Avenue in Chicago. It was home to Muddy Waters, Howlin'' Wolf, Little Walter, Willie Dixon, Sonny Boy Williamson II, Etta James, and Chuck Berry. The Rolling Stones made a pilgrimage there in 1964 and recorded ''2120 South Michigan Avenue'' as a tribute.', 'Chess Records, grunnlagt av de polsk-amerikanske brødrene Leonard og Phil Chess i 1950, hadde hovedkvarter på 2120 South Michigan Avenue i Chicago. Det var hjemmet til Muddy Waters, Howlin'' Wolf, Little Walter, Willie Dixon, Sonny Boy Williamson II, Etta James og Chuck Berry. The Rolling Stones valfartet dit i 1964 og spilte inn ''2120 South Michigan Avenue'' som en hyllest.', 'Chess Records, grundat av de polsk-amerikanska bröderna Leonard och Phil Chess 1950, hade huvudkontor på 2120 South Michigan Avenue i Chicago. Det var hemvist för Muddy Waters, Howlin'' Wolf, Little Walter, Willie Dixon, Sonny Boy Williamson II, Etta James och Chuck Berry. The Rolling Stones vallfärdade dit 1964 och spelade in ''2120 South Michigan Avenue'' som en hyllning.', 'Chess Records, gegründet von den polnisch-amerikanischen Brüdern Leonard und Phil Chess im Jahr 1950, hatte seinen Sitz in der 2120 South Michigan Avenue in Chicago. Es war die Heimat von Muddy Waters, Howlin'' Wolf, Little Walter, Willie Dixon, Sonny Boy Williamson II, Etta James und Chuck Berry. Die Rolling Stones pilgerten 1964 dorthin und nahmen ''2120 South Michigan Avenue'' als Hommage auf.', 'Chess Records, założona przez polsko-amerykańskich braci Leonarda i Phila Chess w 1950 roku, miała siedzibę przy 2120 South Michigan Avenue w Chicago. Była domem dla Muddy''ego Watersa, Howlin'' Wolfa, Little Waltera, Williego Dixona, Sonny''ego Boy Williamsona II, Etty James i Chucka Berry''ego. The Rolling Stones odbyli tam pielgrzymkę w 1964 roku i nagrali ''2120 South Michigan Avenue'' jako hołd.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-8', 'multiple-choice', 'medium',
  'Which artist popularized electric guitar in blues during the 1940s–50s?', 'Hvilken artist populariserte elektrisk gitar i blues på 1940–50-tallet?', 'Vilken artist populariserade elgitarr inom blues under 1940–50-talet?', 'Welcher Künstler machte die E-Gitarre im Blues der 1940er–50er-Jahre populär?', 'Który artysta spopularyzował gitarę elektryczną w bluesie w latach 40.–50.?',
  '["T-Bone Walker","Elmore James","Muddy Waters","Howlin'' Wolf"]', '["T-Bone Walker","Elmore James","Muddy Waters","Howlin'' Wolf"]', '["T-Bone Walker","Elmore James","Muddy Waters","Howlin'' Wolf"]', '["T-Bone Walker","Elmore James","Muddy Waters","Howlin'' Wolf"]', '["T-Bone Walker","Elmore James","Muddy Waters","Howlin'' Wolf"]',
  0,
  'Aaron Thibeaux ''T-Bone'' Walker (1910–1975) was the first blues musician to use an electric guitar as a lead instrument. His 1947 recording ''Call It Stormy Monday (But Tuesday Is Just as Bad)'' is one of the most covered blues songs ever. He also pioneered showmanship – playing guitar behind his head and doing the splits, moves later adopted by Jimi Hendrix and Chuck Berry.', 'Aaron Thibeaux ''T-Bone'' Walker (1910–1975) var den første bluesmusikeren som brukte elektrisk gitar som soloinstrument. Hans innspilling ''Call It Stormy Monday (But Tuesday Is Just as Bad)'' fra 1947 er en av de mest covrede bluessangene noensinne. Han var også en pioner innen showmanship – spilte gitar bak hodet og gjorde spagaten, bevegelser som senere ble adoptert av Jimi Hendrix og Chuck Berry.', 'Aaron Thibeaux ''T-Bone'' Walker (1910–1975) var den första bluesmusikern som använde elgitarr som soloinstrument. Hans inspelning ''Call It Stormy Monday (But Tuesday Is Just as Bad)'' från 1947 är en av de mest coverade bluesarna någonsin. Han var också en pionjär inom showmanship – spelade gitarr bakom huvudet och gjorde spagat, rörelser som senare togs upp av Jimi Hendrix och Chuck Berry.', 'Aaron Thibeaux ''T-Bone'' Walker (1910–1975) war der erste Bluesmusiker, der eine E-Gitarre als Leadinstrument einsetzte. Seine Aufnahme ''Call It Stormy Monday (But Tuesday Is Just as Bad)'' von 1947 ist einer der meistgecoverten Blues-Songs überhaupt. Er war auch ein Pionier der Bühnenshow – spielte Gitarre hinter dem Kopf und machte den Spagat, Bewegungen, die später von Jimi Hendrix und Chuck Berry übernommen wurden.', 'Aaron Thibeaux ''T-Bone'' Walker (1910–1975) był pierwszym muzykiem bluesowym, który używał gitary elektrycznej jako instrumentu prowadzącego. Jego nagranie ''Call It Stormy Monday (But Tuesday Is Just as Bad)'' z 1947 roku jest jedną z najczęściej coverowanych piosenek bluesowych w historii. Był też pionierem scenicznej ekspresji – grał na gitarze za głową i robił szpagat, ruchy później przejęte przez Jimiego Hendrixa i Chucka Berry''ego.',
  't-bone-walker', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-9', 'multiple-choice', 'medium',
  'Which song is considered the first commercial blues recording (1920)?', 'Hvilken sang regnes som den første kommersielle blues-innspillingen (1920)?', 'Vilken låt anses vara den första kommersiella blues-inspelningen (1920)?', 'Welcher Song gilt als die erste kommerzielle Blues-Aufnahme (1920)?', 'Który utwór uznaje się za pierwsze komercyjne nagranie bluesowe (1920)?',
  '["Crazy Blues – Mamie Smith","St. Louis Blues","Cross Road Blues","Pony Blues"]', '["Crazy Blues – Mamie Smith","St. Louis Blues","Cross Road Blues","Pony Blues"]', '["Crazy Blues – Mamie Smith","St. Louis Blues","Cross Road Blues","Pony Blues"]', '["Crazy Blues – Mamie Smith","St. Louis Blues","Cross Road Blues","Pony Blues"]', '["Crazy Blues – Mamie Smith","St. Louis Blues","Cross Road Blues","Pony Blues"]',
  0,
  '''Crazy Blues'' by Mamie Smith, recorded on August 10, 1920 for Okeh Records in New York, is considered the first commercially successful blues recording. It sold 75,000 copies in its first month and over one million total, proving that there was a massive market for African American music and launching the ''race records'' era.', '''Crazy Blues'' av Mamie Smith, spilt inn 10. august 1920 for Okeh Records i New York, regnes som den første kommersielt vellykkede blues-innspillingen. Den solgte 75 000 eksemplarer den første måneden og over én million totalt, noe som beviste at det fantes et enormt marked for afroamerikansk musikk og lanserte ''race records''-æraen.', '''Crazy Blues'' av Mamie Smith, inspelad den 10 augusti 1920 för Okeh Records i New York, anses vara den första kommersiellt framgångsrika blues-inspelningen. Den sålde 75 000 exemplar under sin första månad och över en miljon totalt, vilket bevisade att det fanns en enorm marknad för afroamerikansk musik och inledde ''race records''-eran.', '''Crazy Blues'' von Mamie Smith, aufgenommen am 10. August 1920 für Okeh Records in New York, gilt als die erste kommerziell erfolgreiche Blues-Aufnahme. Sie verkaufte sich im ersten Monat 75.000 Mal und insgesamt über eine Million Mal, was bewies, dass es einen riesigen Markt für afroamerikanische Musik gab, und leitete die Ära der ''Race Records'' ein.', '''Crazy Blues'' Mamie Smith, nagrany 10 sierpnia 1920 roku dla Okeh Records w Nowym Jorku, jest uważany za pierwsze komercyjnie udane nagranie bluesowe. Sprzedał się w nakładzie 75 000 egzemplarzy w pierwszym miesiącu i ponad miliona łącznie, dowodząc, że istniał ogromny rynek na muzykę afroamerykańską, i zapoczątkował erę ''race records''.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-12', 'multiple-choice', 'medium',
  'Who wrote ''The Thrill Is Gone''?', 'Hvem skrev ''The Thrill Is Gone''?', 'Vem skrev ''The Thrill Is Gone''?', 'Wer schrieb ''The Thrill Is Gone''?', 'Kto napisał ''The Thrill Is Gone''?',
  '["B.B. King","Roy Hawkins","Albert King","Freddie King"]', '["B.B. King","Roy Hawkins","Albert King","Freddie King"]', '["B.B. King","Roy Hawkins","Albert King","Freddie King"]', '["B.B. King","Roy Hawkins","Albert King","Freddie King"]', '["B.B. King","Roy Hawkins","Albert King","Freddie King"]',
  1,
  '''The Thrill Is Gone'' was written by Roy Hawkins and Rick Darnell and first recorded by Hawkins in 1951 for Modern Records. B.B. King''s iconic 1969 version, recorded at the Hit Factory in New York with lush string arrangements by Bert de Coteaux, reached #3 on the R&B charts and won a Grammy. It became the most recognizable blues song in the world.', '''The Thrill Is Gone'' ble skrevet av Roy Hawkins og Rick Darnell og først spilt inn av Hawkins i 1951 for Modern Records. B.B. Kings ikoniske versjon fra 1969, innspilt på Hit Factory i New York med frodige strykearrangementer av Bert de Coteaux, nådde 3. plass på R&B-listene og vant en Grammy. Den ble den mest gjenkjennelige bluessangen i verden.', '''The Thrill Is Gone'' skrevs av Roy Hawkins och Rick Darnell och spelades först in av Hawkins 1951 för Modern Records. B.B. Kings ikoniska version från 1969, inspelad på Hit Factory i New York med frodiga stråkarrangemang av Bert de Coteaux, nådde 3:e plats på R&B-listorna och vann en Grammy. Den blev den mest igenkännbara bluesarna i världen.', '''The Thrill Is Gone'' wurde von Roy Hawkins und Rick Darnell geschrieben und erstmals 1951 von Hawkins für Modern Records aufgenommen. B.B. Kings ikonische Version von 1969, aufgenommen in der Hit Factory in New York mit üppigen Streicherarrangements von Bert de Coteaux, erreichte Platz 3 der R&B-Charts und gewann einen Grammy. Er wurde zum bekanntesten Blues-Song der Welt.', '''The Thrill Is Gone'' zostało napisane przez Roya Hawkinsa i Ricka Darnella, a po raz pierwszy nagrane przez Hawkinsa w 1951 roku dla Modern Records. Kultowa wersja B.B. Kinga z 1969 roku, nagrana w Hit Factory w Nowym Jorku z bogatymi aranżacjami smyczkowymi Berta de Coteaux, dotarła na 3. miejsce list R&B i zdobyła Grammy. Stała się najbardziej rozpoznawalną piosenką bluesową na świecie.',
  'bb-king', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-16', 'multiple-choice', 'medium',
  'Which artist recorded ''Dust My Broom'' in 1951?', 'Hvilken artist spilte inn ''Dust My Broom'' i 1951?', 'Vilken artist spelade in ''Dust My Broom'' 1951?', 'Welcher Künstler nahm ''Dust My Broom'' 1951 auf?', 'Który artysta nagrał ''Dust My Broom'' w 1951 roku?',
  '["Robert Johnson","Elmore James","Muddy Waters","Howlin'' Wolf"]', '["Robert Johnson","Elmore James","Muddy Waters","Howlin'' Wolf"]', '["Robert Johnson","Elmore James","Muddy Waters","Howlin'' Wolf"]', '["Robert Johnson","Elmore James","Muddy Waters","Howlin'' Wolf"]', '["Robert Johnson","Elmore James","Muddy Waters","Howlin'' Wolf"]',
  1,
  'Elmore James (1918–1963) recorded his electrified version of ''Dust My Broom'' for Trumpet Records in Jackson, Mississippi in 1951, with Sonny Boy Williamson II on harmonica. The opening slide guitar riff – based on Robert Johnson''s 1936 original – became one of the most recognizable in all of blues and has been copied by countless guitarists.', 'Elmore James (1918–1963) spilte inn sin elektrifiserte versjon av ''Dust My Broom'' for Trumpet Records i Jackson, Mississippi i 1951, med Sonny Boy Williamson II på munnspill. Det ikoniske åpningsriffet på slidegitar – basert på Robert Johnsons original fra 1936 – ble et av de mest gjenkjennelige i all blues og har blitt kopiert av utallige gitarister.', 'Elmore James (1918–1963) spelade in sin elektrifierade version av ''Dust My Broom'' för Trumpet Records i Jackson, Mississippi 1951, med Sonny Boy Williamson II på munspel. Det ikoniska öppningsriffet på slidegitarr – baserat på Robert Johnsons original från 1936 – blev ett av de mest igenkännbara i all blues och har kopierats av otaliga gitarrister.', 'Elmore James (1918–1963) nahm seine elektrifizierte Version von ''Dust My Broom'' 1951 für Trumpet Records in Jackson, Mississippi auf, mit Sonny Boy Williamson II an der Mundharmonika. Das einleitende Slide-Gitarrenriff – basierend auf Robert Johnsons Original von 1936 – wurde eines der erkennbarsten im gesamten Blues und wurde von unzähligen Gitarristen kopiert.', 'Elmore James (1918–1963) nagrał swoją zelektryfikowaną wersję ''Dust My Broom'' dla Trumpet Records w Jackson w stanie Mississippi w 1951 roku, z Sonnym Boyem Williamsonem II na harmonijce. Otwierający riff na gitarze slide – oparty na oryginale Roberta Johnsona z 1936 roku – stał się jednym z najbardziej rozpoznawalnych w całym bluesie i był kopiowany przez niezliczonych gitarzystów.',
  'elmore-james', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-18', 'multiple-choice', 'medium',
  'Which Texas blues guitarist died in a helicopter crash in 1990?', 'Hvilken Texas blues-gitarist døde i en helikopterstyrt i 1990?', 'Vilken Texas blues-gitarrist dog i en helikopterolycka 1990?', 'Welcher Texas-Blues-Gitarrist starb 1990 bei einem Hubschrauberabsturz?', 'Który teksański gitarzysta bluesowy zginął w katastrofie helikoptera w 1990 roku?',
  '["Freddie King","Albert Collins","Stevie Ray Vaughan","Johnny Winter"]', '["Freddie King","Albert Collins","Stevie Ray Vaughan","Johnny Winter"]', '["Freddie King","Albert Collins","Stevie Ray Vaughan","Johnny Winter"]', '["Freddie King","Albert Collins","Stevie Ray Vaughan","Johnny Winter"]', '["Freddie King","Albert Collins","Stevie Ray Vaughan","Johnny Winter"]',
  2,
  'Stevie Ray Vaughan (1954–1990) died in a helicopter crash at Alpine Valley Music Theatre in East Troy, Wisconsin on August 27, 1990, just hours after performing alongside Eric Clapton, Buddy Guy, and Robert Cray. He was 35 years old and had just overcome addiction. His album ''Texas Flood'' (1983) is considered one of the greatest blues albums ever recorded.', 'Stevie Ray Vaughan (1954–1990) døde i en helikopterstyrt ved Alpine Valley Music Theatre i East Troy, Wisconsin 27. august 1990, bare timer etter å ha opptrådt sammen med Eric Clapton, Buddy Guy og Robert Cray. Han var 35 år gammel og hadde nettopp overvunnet avhengighet. Albumet hans ''Texas Flood'' (1983) regnes som et av de største bluesalbumene noensinne.', 'Stevie Ray Vaughan (1954–1990) dog i en helikopterolycka vid Alpine Valley Music Theatre i East Troy, Wisconsin den 27 augusti 1990, bara timmar efter att ha uppträtt tillsammans med Eric Clapton, Buddy Guy och Robert Cray. Han var 35 år gammal och hade precis övervunnit missbruk. Hans album ''Texas Flood'' (1983) anses vara ett av de största bluesalbumen någonsin.', 'Stevie Ray Vaughan (1954–1990) starb am 27. August 1990 bei einem Hubschrauberabsturz am Alpine Valley Music Theatre in East Troy, Wisconsin, nur Stunden nachdem er zusammen mit Eric Clapton, Buddy Guy und Robert Cray aufgetreten war. Er war 35 Jahre alt und hatte gerade eine Sucht überwunden. Sein Album ''Texas Flood'' (1983) gilt als eines der größten Blues-Alben aller Zeiten.', 'Stevie Ray Vaughan (1954–1990) zginął w katastrofie helikoptera przy Alpine Valley Music Theatre w East Troy w stanie Wisconsin 27 sierpnia 1990 roku, zaledwie kilka godzin po występie u boku Erica Claptona, Buddy''ego Guya i Roberta Craya. Miał 35 lat i właśnie pokonał uzależnienie. Jego album ''Texas Flood'' (1983) uważany jest za jeden z największych albumów bluesowych, jakie kiedykolwiek nagrano.',
  'stevie-ray-vaughan', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-20', 'multiple-choice', 'medium',
  'Who was known for using ''cross harp'' on harmonica?', 'Hvem var kjent for å bruke ''cross harp'' på munnspill?', 'Vem var känd för att använda ''cross harp'' på munspel?', 'Wer war bekannt für die Verwendung von ''Cross Harp'' auf der Mundharmonika?', 'Kto był znany z używania techniki ''cross harp'' na harmonijce ustnej?',
  '["Sonny Boy Williamson I","Little Walter","Big Walter Horton","Junior Wells"]', '["Sonny Boy Williamson I","Little Walter","Big Walter Horton","Junior Wells"]', '["Sonny Boy Williamson I","Little Walter","Big Walter Horton","Junior Wells"]', '["Sonny Boy Williamson I","Little Walter","Big Walter Horton","Junior Wells"]', '["Sonny Boy Williamson I","Little Walter","Big Walter Horton","Junior Wells"]',
  1,
  'Little Walter revolutionized blues harmonica by mastering ''cross harp'' (2nd position) – playing a harmonica in a different key than it''s tuned to, which allows for more expressive bending and blue notes. Combined with his innovation of amplifying the harmonica through a cupped microphone, he created a sound so powerful that the harmonica became a lead instrument rivaling the guitar.', 'Little Walter revolusjonerte blues-munnspillet ved å mestre ''cross harp'' (2. posisjon) – å spille et munnspill i en annen toneart enn det er stemt i, noe som tillater mer ekspressiv bøying og blue notes. Kombinert med hans innovasjon med å forsterke munnspillet gjennom en mikrofon holdt i hendene, skapte han en lyd så kraftfull at munnspillet ble et soloinstrument som rivaliserte gitaren.', 'Little Walter revolutionerade blues-munspelet genom att bemästra ''cross harp'' (2:a positionen) – att spela ett munspel i en annan tonart än den är stämd i, vilket möjliggör mer uttrycksfull böjning och blue notes. Kombinerat med hans innovation att förstärka munspelet genom en kupad mikrofon skapade han ett ljud så kraftfullt att munspelet blev ett soloinstrument som rivaliserade gitarren.', 'Little Walter revolutionierte die Blues-Mundharmonika, indem er ''Cross Harp'' (2. Position) meisterte – das Spielen einer Mundharmonika in einer anderen Tonart, als sie gestimmt ist, was ausdrucksvolleres Bending und Blue Notes ermöglicht. Kombiniert mit seiner Innovation, die Mundharmonika durch ein in den Händen gehaltenes Mikrofon zu verstärken, schuf er einen Sound, der so kraftvoll war, dass die Mundharmonika zu einem Leadinstrument wurde, das mit der Gitarre konkurrierte.', 'Little Walter zrewolucjonizował harmonijkę bluesową, opanowując ''cross harp'' (2. pozycję) – granie na harmonijce w innej tonacji niż ta, w której jest nastrojona, co pozwala na bardziej ekspresyjne przeginanie dźwięków i blue notes. W połączeniu z jego innowacją wzmacniania harmonijki przez mikrofon trzymany w złożonych dłoniach, stworzył dźwięk tak potężny, że harmonijka stała się instrumentem prowadzącym rywalizującym z gitarą.',
  'little-walter', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-21', 'multiple-choice', 'medium',
  'Which Scandinavian guitarist is known for his bottleneck slide and roots blues?', 'Hvilken skandinavisk gitarist er kjent for sin bottleneck slide og roots blues?', 'Vilken skandinavisk gitarrist är känd för sin bottleneck slide och roots blues?', 'Welcher skandinavische Gitarrist ist bekannt für seinen Bottleneck-Slide und Roots-Blues?', 'Który skandynawski gitarzysta jest znany z gry slide bottleneck i roots bluesa?',
  '["Vidar Busk","Knut Reiersrud","Amund Maarud","Erja Lyytinen"]', '["Vidar Busk","Knut Reiersrud","Amund Maarud","Erja Lyytinen"]', '["Vidar Busk","Knut Reiersrud","Amund Maarud","Erja Lyytinen"]', '["Vidar Busk","Knut Reiersrud","Amund Maarud","Erja Lyytinen"]', '["Vidar Busk","Knut Reiersrud","Amund Maarud","Erja Lyytinen"]',
  1,
  'Knut Reiersrud (b. 1961) is Norway''s most internationally acclaimed blues and roots musician. A master of bottleneck slide guitar, he has collaborated with artists across the globe – from Mali to Mississippi – blending Norwegian folk traditions with deep Delta blues. He has won multiple Spellemannpriser and performed at major blues festivals worldwide.', 'Knut Reiersrud (f. 1961) er Norges mest internasjonalt anerkjente blues- og rootsmusiker. En mester på bottleneck slidegitar, har han samarbeidet med artister over hele verden – fra Mali til Mississippi – og blander norske folktradisjoner med dyp Delta blues. Han har vunnet flere Spellemannpriser og opptrådt på store bluesfestivaler verden over.', 'Knut Reiersrud (f. 1961) är Norges mest internationellt hyllade blues- och rootsmusiker. En mästare på bottleneck slidegitarr, har han samarbetat med artister runt om i världen – från Mali till Mississippi – och blandar norska folktraditioner med djup Delta blues. Han har vunnit flera Spellemannpriser och uppträtt på stora bluesfestivaler världen över.', 'Knut Reiersrud (geb. 1961) ist Norwegens international angesehenster Blues- und Roots-Musiker. Als Meister der Bottleneck-Slide-Gitarre hat er mit Künstlern rund um den Globus zusammengearbeitet – von Mali bis Mississippi – und verbindet norwegische Volkstraditionen mit tiefem Delta Blues. Er hat mehrere Spellemannpriser gewonnen und bei großen Bluesfestivals weltweit gespielt.', 'Knut Reiersrud (ur. 1961) jest najbardziej uznanym na arenie międzynarodowej norweskim muzykiem bluesowym i rootsowym. Mistrz gry slide bottleneck, współpracował z artystami z całego świata – od Mali po Mississippi – łącząc norweskie tradycje ludowe z głębokim Delta bluesem. Zdobył wiele nagród Spellemannpris i występował na największych festiwalach bluesowych na świecie.',
  'knut-reiersrud', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-23', 'multiple-choice', 'medium',
  'Which British guitarist led the Bluesbreakers and mentored Eric Clapton?', 'Hvilken britisk gitarist ledet Bluesbreakers og veiledet Eric Clapton?', 'Vilken brittisk gitarrist ledde Bluesbreakers och var mentor åt Eric Clapton?', 'Welcher britische Gitarrist leitete die Bluesbreakers und war Mentor von Eric Clapton?', 'Który brytyjski gitarzysta prowadził Bluesbreakers i był mentorem Erica Claptona?',
  '["Peter Green","John Mayall","Alexis Korner","Jeff Beck"]', '["Peter Green","John Mayall","Alexis Korner","Jeff Beck"]', '["Peter Green","John Mayall","Alexis Korner","Jeff Beck"]', '["Peter Green","John Mayall","Alexis Korner","Jeff Beck"]', '["Peter Green","John Mayall","Alexis Korner","Jeff Beck"]',
  1,
  'John Mayall (1933–2024), ''The Godfather of British Blues,'' led his Bluesbreakers as a revolving-door training ground for Britain''s greatest guitarists. Eric Clapton (1965–66), Peter Green (1966–67), and Mick Taylor (1967–69) all served apprenticeships in the band before forming Cream, Fleetwood Mac, and joining The Rolling Stones respectively.', 'John Mayall (1933–2024), ''Gudfaren til britisk blues,'' ledet sine Bluesbreakers som en treningsplass med svingdør for Storbritannias største gitarister. Eric Clapton (1965–66), Peter Green (1966–67) og Mick Taylor (1967–69) gjennomgikk alle læretid i bandet før de dannet henholdsvis Cream, Fleetwood Mac og ble med i The Rolling Stones.', 'John Mayall (1933–2024), ''Gudfadern till brittisk blues,'' ledde sina Bluesbreakers som en genomgångsplats för Storbritanniens främsta gitarrister. Eric Clapton (1965–66), Peter Green (1966–67) och Mick Taylor (1967–69) gick alla i lära i bandet innan de bildade Cream respektive Fleetwood Mac och gick med i The Rolling Stones.', 'John Mayall (1933–2024), ''der Pate des britischen Blues,'' leitete seine Bluesbreakers als Sprungbrett für Großbritanniens größte Gitarristen. Eric Clapton (1965–66), Peter Green (1966–67) und Mick Taylor (1967–69) absolvierten alle ihre Lehrzeit in der Band, bevor sie Cream und Fleetwood Mac gründeten bzw. den Rolling Stones beitraten.', 'John Mayall (1933–2024), ''Ojciec chrzestny brytyjskiego bluesa,'' prowadził swoich Bluesbreakers jako miejsce szkolenia najwybitniejszych brytyjskich gitarzystów. Eric Clapton (1965–66), Peter Green (1966–67) i Mick Taylor (1967–69) odbyli w zespole swój ''staż'', zanim odpowiednio założyli Cream, Fleetwood Mac i dołączyli do The Rolling Stones.',
  'john-mayall-bluesbreakers', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-24', 'multiple-choice', 'medium',
  'Which young guitarist won a Grammy before turning 22 and is from Clarksdale, Mississippi?', 'Hvilken ung gitarist vant en Grammy før han fylte 22 og er fra Clarksdale, Mississippi?', 'Vilken ung gitarrist vann en Grammy innan han fyllde 22 och är från Clarksdale, Mississippi?', 'Welcher junge Gitarrist gewann vor seinem 22. Geburtstag einen Grammy und stammt aus Clarksdale, Mississippi?', 'Który młody gitarzysta zdobył Grammy przed ukończeniem 22 lat i pochodzi z Clarksdale w stanie Mississippi?',
  '["Gary Clark Jr.","Christone ''Kingfish'' Ingram","Marcus King","Jontavious Willis"]', '["Gary Clark Jr.","Christone ''Kingfish'' Ingram","Marcus King","Jontavious Willis"]', '["Gary Clark Jr.","Christone ''Kingfish'' Ingram","Marcus King","Jontavious Willis"]', '["Gary Clark Jr.","Christone ''Kingfish'' Ingram","Marcus King","Jontavious Willis"]', '["Gary Clark Jr.","Christone ''Kingfish'' Ingram","Marcus King","Jontavious Willis"]',
  1,
  'Christone ''Kingfish'' Ingram (b. 1999) from Clarksdale, Mississippi – the birthplace of Delta blues – won a Grammy in 2022 for his album ''662'' (named after Clarksdale''s area code). Mentored by Buddy Guy and endorsed by blues royalty, he represents the living connection between Delta blues'' past and future. His 2019 debut ''Kingfish'' was produced by Tom Hambridge.', 'Christone ''Kingfish'' Ingram (f. 1999) fra Clarksdale, Mississippi – fødestedet til Delta blues – vant en Grammy i 2022 for albumet ''662'' (oppkalt etter Clarksdales retningsnummer). Veiledet av Buddy Guy og godkjent av blues-royalty, representerer han den levende koblingen mellom Delta blues'' fortid og fremtid. Debutalbumet ''Kingfish'' fra 2019 ble produsert av Tom Hambridge.', 'Christone ''Kingfish'' Ingram (f. 1999) från Clarksdale, Mississippi – Delta bluesens födelseort – vann en Grammy 2022 för sitt album ''662'' (uppkallat efter Clarksdales riktnummer). Under mentorskap av Buddy Guy och godkänd av blues-royalty representerar han den levande kopplingen mellan Delta bluesens förflutna och framtid. Debutalbumet ''Kingfish'' från 2019 producerades av Tom Hambridge.', 'Christone ''Kingfish'' Ingram (geb. 1999) aus Clarksdale, Mississippi – dem Geburtsort des Delta Blues – gewann 2022 einen Grammy für sein Album ''662'' (benannt nach Clarksdales Vorwahl). Unter der Mentorschaft von Buddy Guy und mit dem Segen der Blues-Legenden repräsentiert er die lebendige Verbindung zwischen der Vergangenheit und Zukunft des Delta Blues. Sein Debütalbum ''Kingfish'' von 2019 wurde von Tom Hambridge produziert.', 'Christone ''Kingfish'' Ingram (ur. 1999) z Clarksdale w stanie Mississippi – miejsca narodzin Delta bluesa – zdobył Grammy w 2022 roku za album ''662'' (nazwany na cześć numeru kierunkowego Clarksdale). Pod mentoringiem Buddy''ego Guya i uznaniem legend bluesa, reprezentuje żywe połączenie między przeszłością a przyszłością Delta bluesa. Jego debiutancki album ''Kingfish'' z 2019 roku wyprodukował Tom Hambridge.',
  'christone-kingfish-ingram', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-27', 'multiple-choice', 'medium',
  'Which blues festival in Norway has been running since 1988?', 'Hvilken bluesfestival i Norge har pågått siden 1988?', 'Vilken bluesfestival i Norge har pågått sedan 1988?', 'Welches Bluesfestival in Norwegen findet seit 1988 statt?', 'Który festiwal bluesowy w Norwegii odbywa się od 1988 roku?',
  '["Notodden Blues Festival","Hell Blues Festival","Stavanger Blues","Bergen Blues & Roots"]', '["Notodden Blues Festival","Hell Blues Festival","Stavanger Blues","Bergen Blues & Roots"]', '["Notodden Blues Festival","Hell Blues Festival","Stavanger Blues","Bergen Blues & Roots"]', '["Notodden Blues Festival","Hell Blues Festival","Stavanger Blues","Bergen Blues & Roots"]', '["Notodden Blues Festival","Hell Blues Festival","Stavanger Blues","Bergen Blues & Roots"]',
  0,
  'Notodden Blues Festival, held annually in the small industrial town of Notodden (pop. ~12,000) in Telemark, has been one of Europe''s premier blues festivals since 1988. B.B. King, Buddy Guy, Robert Cray, Joe Bonamassa, and hundreds of international acts have graced its stages. The town is also home to the European Blues Museum.', 'Notodden Blues Festival, som holdes årlig i den lille industribyen Notodden (ca. 12 000 innbyggere) i Telemark, har vært en av Europas fremste bluesfestivaler siden 1988. B.B. King, Buddy Guy, Robert Cray, Joe Bonamassa og hundrevis av internasjonale artister har opptrådt der. Byen er også hjemmet til European Blues Museum.', 'Notodden Blues Festival, som hålls årligen i den lilla industristaden Notodden (ca 12 000 invånare) i Telemark, har varit en av Europas främsta bluesfestivaler sedan 1988. B.B. King, Buddy Guy, Robert Cray, Joe Bonamassa och hundratals internationella artister har uppträtt där. Staden är också hemvist för European Blues Museum.', 'Das Notodden Blues Festival, das jährlich in der kleinen Industriestadt Notodden (ca. 12.000 Einwohner) in Telemark stattfindet, ist seit 1988 eines der führenden Bluesfestivals Europas. B.B. King, Buddy Guy, Robert Cray, Joe Bonamassa und Hunderte internationaler Künstler standen auf seinen Bühnen. Die Stadt ist auch Sitz des European Blues Museum.', 'Notodden Blues Festival, odbywający się co roku w małym przemysłowym miasteczku Notodden (ok. 12 000 mieszkańców) w regionie Telemark, jest jednym z czołowych festiwali bluesowych Europy od 1988 roku. B.B. King, Buddy Guy, Robert Cray, Joe Bonamassa i setki międzynarodowych wykonawców występowały na jego scenach. Miasto jest również siedzibą Europejskiego Muzeum Bluesa.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-28', 'multiple-choice', 'medium',
  'Who is Shemekia Copeland''s father?', 'Hvem er Shemekia Copelands far?', 'Vem är Shemekia Copelands far?', 'Wer ist Shemekia Copelands Vater?', 'Kto jest ojcem Shemekii Copeland?',
  '["Buddy Guy","Johnny Copeland","Albert Collins","Freddie King"]', '["Buddy Guy","Johnny Copeland","Albert Collins","Freddie King"]', '["Buddy Guy","Johnny Copeland","Albert Collins","Freddie King"]', '["Buddy Guy","Johnny Copeland","Albert Collins","Freddie King"]', '["Buddy Guy","Johnny Copeland","Albert Collins","Freddie King"]',
  1,
  'Shemekia Copeland (b. 1979) is the daughter of Houston-born Texas blues guitarist Johnny Copeland (1937–1997), who won a Grammy in 1985 for ''Showdown!'' alongside Albert Collins and Robert Cray. Shemekia made her stage debut at age 8 at Harlem''s Cotton Club and has won multiple Blues Music Awards, carrying on her father''s legacy with a voice that can shake buildings.', 'Shemekia Copeland (f. 1979) er datteren til Houston-fødte Texas blues-gitaristen Johnny Copeland (1937–1997), som vant en Grammy i 1985 for ''Showdown!'' sammen med Albert Collins og Robert Cray. Shemekia debuterte på scenen som 8-åring på Cotton Club i Harlem og har vunnet flere Blues Music Awards, og fører farens arv videre med en stemme som kan få bygninger til å riste.', 'Shemekia Copeland (f. 1979) är dotter till den Houston-födda Texas blues-gitarristen Johnny Copeland (1937–1997), som vann en Grammy 1985 för ''Showdown!'' tillsammans med Albert Collins och Robert Cray. Shemekia gjorde scendebut som 8-åring på Cotton Club i Harlem och har vunnit flera Blues Music Awards, och för sin fars arv vidare med en röst som kan få byggnader att skaka.', 'Shemekia Copeland (geb. 1979) ist die Tochter des in Houston geborenen Texas-Blues-Gitarristen Johnny Copeland (1937–1997), der 1985 zusammen mit Albert Collins und Robert Cray einen Grammy für ''Showdown!'' gewann. Shemekia gab ihr Bühnendebüt im Alter von 8 Jahren im Cotton Club in Harlem und hat mehrere Blues Music Awards gewonnen, wobei sie das Erbe ihres Vaters mit einer Stimme fortführt, die Gebäude erzittern lässt.', 'Shemekia Copeland (ur. 1979) jest córką urodzonego w Houston teksańskiego gitarzysty bluesowego Johnny''ego Copelanda (1937–1997), który zdobył Grammy w 1985 roku za album ''Showdown!'' wraz z Albertem Collinsem i Robertem Crayem. Shemekia zadebiutowała na scenie w wieku 8 lat w Cotton Club w Harlemie i zdobyła wiele nagród Blues Music Awards, kontynuując dziedzictwo ojca głosem, który potrafi wstrząsnąć budynkami.',
  'shemekia-copeland', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-32', 'multiple-choice', 'medium',
  'Which guitarist is known for playing his guitar left-handed and upside down?', 'Hvilken gitarist er kjent for å spille gitaren venstrehendt og opp-ned?', 'Vilken gitarrist är känd för att spela sin gitarr vänsterhänt och upp och ner?', 'Welcher Gitarrist ist dafür bekannt, seine Gitarre linkshändig und verkehrt herum zu spielen?', 'Który gitarzysta jest znany z gry na gitarze leworęcznie i do góry nogami?',
  '["Buddy Guy","Albert King","Freddie King","B.B. King"]', '["Buddy Guy","Albert King","Freddie King","B.B. King"]', '["Buddy Guy","Albert King","Freddie King","B.B. King"]', '["Buddy Guy","Albert King","Freddie King","B.B. King"]', '["Buddy Guy","Albert King","Freddie King","B.B. King"]',
  1,
  'Albert King (1923–1992) played a right-handed Gibson Flying V upside down as a left-hander, meaning he pulled the strings downward for his bends instead of pushing them up. This gave him his signature powerful, vocal-like string bending style that directly influenced Stevie Ray Vaughan, who called Albert ''the master.'' His 1967 album ''Born Under a Bad Sign'' is a cornerstone of modern blues.', 'Albert King (1923–1992) spilte en høyrehendt Gibson Flying V opp-ned som venstrehendt, noe som betydde at han trakk strengene nedover for sine bøyninger i stedet for å skyve dem opp. Dette ga ham hans signatur kraftfulle, vokal-lignende strengbøyningsstil som direkte påvirket Stevie Ray Vaughan, som kalte Albert ''mesteren.'' Albumet ''Born Under a Bad Sign'' fra 1967 er en hjørnestein i moderne blues.', 'Albert King (1923–1992) spelade en högerhänt Gibson Flying V upp och ner som vänsterhänt, vilket innebar att han drog strängarna nedåt för sina böjningar istället för att trycka upp dem. Detta gav honom hans signatur kraftfulla, röstlika strängböjningsstil som direkt påverkade Stevie Ray Vaughan, som kallade Albert ''mästaren.'' Hans album ''Born Under a Bad Sign'' från 1967 är en hörnsten i modern blues.', 'Albert King (1923–1992) spielte eine rechtshändige Gibson Flying V verkehrt herum als Linkshänder, was bedeutete, dass er die Saiten für seine Bendings nach unten statt nach oben zog. Dies verlieh ihm seinen unverwechselbaren, kraftvollen, gesangsähnlichen Saitenbending-Stil, der Stevie Ray Vaughan direkt beeinflusste, der Albert ''den Meister'' nannte. Sein Album ''Born Under a Bad Sign'' von 1967 ist ein Eckpfeiler des modernen Blues.', 'Albert King (1923–1992) grał na praworęcznej gitarze Gibson Flying V odwróconej do góry nogami jako leworęczny, co oznaczało, że ciągnął struny w dół podczas przeginania zamiast pchać je w górę. To dało mu charakterystyczny, potężny, przypominający głos styl przeginania strun, który bezpośrednio wpłynął na Stevie''ego Raya Vaughana, który nazwał Alberta ''mistrzem.'' Jego album ''Born Under a Bad Sign'' z 1967 roku jest kamieniem węgielnym współczesnego bluesa.',
  'albert-king', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-35', 'multiple-choice', 'medium',
  'Which Finnish blues guitarist is known for her slide guitar mastery?', 'Hvilken finsk bluesgitarist er kjent for sin slidegitarmestring?', 'Vilken finsk bluesgitarrist är känd för sin bemästring av slidegitarr?', 'Welche finnische Blues-Gitarristin ist bekannt für ihre Meisterschaft auf der Slide-Gitarre?', 'Która fińska gitarzystka bluesowa jest znana z mistrzostwa gry na gitarze slide?',
  '["Louise Hoffsten","Erja Lyytinen","Rita Engedalen","Sue Foley"]', '["Louise Hoffsten","Erja Lyytinen","Rita Engedalen","Sue Foley"]', '["Louise Hoffsten","Erja Lyytinen","Rita Engedalen","Sue Foley"]', '["Louise Hoffsten","Erja Lyytinen","Rita Engedalen","Sue Foley"]', '["Louise Hoffsten","Erja Lyytinen","Rita Engedalen","Sue Foley"]',
  1,
  'Erja Lyytinen (b. 1976) from Kuopio, Finland, is one of Europe''s finest blues guitarists, known internationally for her exceptional slide guitar technique. She studied at the Helsinki Conservatory and Musician''s Institute in Los Angeles, and has been called ''the new Empress of the Blues'' by Guitar World magazine. She has performed with Joe Bonamassa and at major festivals worldwide.', 'Erja Lyytinen (f. 1976) fra Kuopio, Finland, er en av Europas fineste bluesgitarister, internasjonalt kjent for sin eksepsjonelle slidegitarteknikk. Hun studerte ved Helsinki Conservatory og Musician''s Institute i Los Angeles, og har blitt kalt ''den nye keiserinnen av blues'' av Guitar World magazine. Hun har opptrådt med Joe Bonamassa og på store festivaler verden over.', 'Erja Lyytinen (f. 1976) från Kuopio, Finland, är en av Europas finaste bluesgitarrister, internationellt känd för sin exceptionella slidegitarrteknik. Hon studerade vid Helsinki Conservatory och Musician''s Institute i Los Angeles, och har kallats ''den nya blueskejsarinnan'' av Guitar World magazine. Hon har uppträtt med Joe Bonamassa och på stora festivaler världen över.', 'Erja Lyytinen (geb. 1976) aus Kuopio, Finnland, ist eine der besten Blues-Gitarristinnen Europas, international bekannt für ihre außergewöhnliche Slide-Gitarrentechnik. Sie studierte am Helsinki Conservatory und am Musician''s Institute in Los Angeles und wurde vom Guitar World Magazine ''die neue Kaiserin des Blues'' genannt. Sie hat mit Joe Bonamassa und bei großen Festivals weltweit gespielt.', 'Erja Lyytinen (ur. 1976) z Kuopio w Finlandii jest jedną z najlepszych europejskich gitarzystek bluesowych, znaną na całym świecie ze swojej wyjątkowej techniki gry na gitarze slide. Studiowała w Helsinki Conservatory oraz Musician''s Institute w Los Angeles, a magazyn Guitar World nazwał ją ''nową cesarzową bluesa.'' Występowała z Joe Bonamassą i na największych festiwalach na świecie.',
  'erja-lyytinen', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-19', 'multiple-choice', 'hard',
  'Who founded Paramount Records, which recorded many early blues artists?', 'Hvem grunnla Paramount Records, som spilte inn mange tidlige bluesartister?', 'Vem grundade Paramount Records, som spelade in många tidiga bluesartister?', 'Wer gründete Paramount Records, das viele frühe Bluesmusiker aufnahm?', 'Kto założył Paramount Records, wytwórnię, która nagrała wielu wczesnych artystów bluesowych?',
  '["Leonard Chess","Sam Phillips","Wisconsin Chair Company","John Hammond"]', '["Leonard Chess","Sam Phillips","Wisconsin Chair Company","John Hammond"]', '["Leonard Chess","Sam Phillips","Wisconsin Chair Company","John Hammond"]', '["Leonard Chess","Sam Phillips","Wisconsin Chair Company","John Hammond"]', '["Leonard Chess","Sam Phillips","Wisconsin Chair Company","John Hammond"]',
  2,
  'Paramount Records was founded in 1917 by the Wisconsin Chair Company in Port Washington, Wisconsin – originally to sell phonograph cabinets! They needed records to demonstrate their cabinets, leading them to record music. Between 1922–1932 they recorded crucial early blues by Charley Patton, Blind Lemon Jefferson, Ma Rainey, Skip James, and Son House. Despite poor recording quality, these recordings are now priceless documents of early blues.', 'Paramount Records ble grunnlagt i 1917 av Wisconsin Chair Company i Port Washington, Wisconsin – opprinnelig for å selge grammofon-kabinetter! De trengte plater for å demonstrere kabinettene, noe som førte til at de begynte å spille inn musikk. Mellom 1922–1932 spilte de inn avgjørende tidlig blues av Charley Patton, Blind Lemon Jefferson, Ma Rainey, Skip James og Son House. Til tross for dårlig innspillingskvalitet er disse innspillingene nå uvurderlige dokumenter av tidlig blues.', 'Paramount Records grundades 1917 av Wisconsin Chair Company i Port Washington, Wisconsin – ursprungligen för att sälja grammofonskåp! De behövde skivor för att demonstrera sina skåp, vilket ledde till att de började spela in musik. Mellan 1922–1932 spelade de in avgörande tidig blues av Charley Patton, Blind Lemon Jefferson, Ma Rainey, Skip James och Son House. Trots dålig inspelningskvalitet är dessa inspelningar nu ovärderliga dokument av tidig blues.', 'Paramount Records wurde 1917 von der Wisconsin Chair Company in Port Washington, Wisconsin, gegründet – ursprünglich, um Phonographenschränke zu verkaufen! Sie brauchten Schallplatten, um ihre Schränke vorzuführen, was dazu führte, dass sie Musik aufnahmen. Zwischen 1922 und 1932 nahmen sie entscheidenden frühen Blues von Charley Patton, Blind Lemon Jefferson, Ma Rainey, Skip James und Son House auf. Trotz schlechter Aufnahmequalität sind diese Aufnahmen heute unbezahlbare Dokumente des frühen Blues.', 'Paramount Records zostało założone w 1917 roku przez Wisconsin Chair Company w Port Washington w stanie Wisconsin – pierwotnie w celu sprzedaży szafek do gramofonów! Potrzebowali płyt, aby zademonstrować swoje szafki, co doprowadziło do nagrywania muzyki. W latach 1922–1932 nagrali kluczowe wczesne nagrania bluesowe Charleya Pattona, Blinda Lemona Jeffersona, Ma Rainey, Skipa Jamesa i Sona House''a. Mimo słabej jakości nagrania są dziś bezcennymi dokumentami wczesnego bluesa.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-22', 'multiple-choice', 'hard',
  'What was the ''Great Migration'' and how did it affect blues?', 'Hva var ''Den store migrasjonen'' og hvordan påvirket den blues?', 'Vad var ''Den stora migrationen'' och hur påverkade den blues?', 'Was war die ''Great Migration'' und wie beeinflusste sie den Blues?', 'Czym była ''Wielka Migracja'' i jak wpłynęła na bluesa?',
  '["A music festival in Chicago","Mass movement of African Americans from the South to northern cities","A record label merger in the 1960s","A tour by British blues bands in America"]', '["En musikkfestival i Chicago","Massebevegelse av afroamerikanere fra sør til nordlige byer","En plateselskapsfusjon på 1960-tallet","En turné av britiske bluesband i Amerika"]', '["En musikfestival i Chicago","Massrörelse av afroamerikaner från söder till norra städer","En skivbolagsfusion på 1960-talet","En turné av brittiska bluesband i Amerika"]', '["Ein Musikfestival in Chicago","Massenbewegung von Afroamerikanern vom Süden in nördliche Städte","Eine Plattenlabel-Fusion in den 1960er-Jahren","Eine Tour britischer Bluesbands durch Amerika"]', '["Festiwal muzyczny w Chicago","Masowe przemieszczenie się Afroamerykanów z Południa do miast na Północy","Fuzja wytwórni płytowych w latach 60.","Trasa koncertowa brytyjskich zespołów bluesowych po Ameryce"]',
  1,
  'The Great Migration (1910–1970) saw approximately 6 million African Americans leave the rural South for cities like Chicago, Detroit, Memphis, and New York. Musicians like Muddy Waters (who left Stovall Plantation, Mississippi for Chicago in 1943) brought acoustic Delta blues north and electrified it, creating Chicago blues. This migration literally transformed American music, leading to blues, R&B, soul, rock ''n'' roll, and eventually hip-hop.', 'Den store migrasjonen (1910–1970) så omtrent 6 millioner afroamerikanere forlate det rurale sørstatene for byer som Chicago, Detroit, Memphis og New York. Musikere som Muddy Waters (som forlot Stovall Plantation, Mississippi til Chicago i 1943) brakte akustisk Delta blues nordover og elektrifiserte den, og skapte Chicago blues. Denne migrasjonen transformerte bokstavelig talt amerikansk musikk, og førte til blues, R&B, soul, rock ''n'' roll og til slutt hip-hop.', 'Den stora migrationen (1910–1970) såg cirka 6 miljoner afroamerikaner lämna det rurala Södern för städer som Chicago, Detroit, Memphis och New York. Musiker som Muddy Waters (som lämnade Stovall Plantation, Mississippi för Chicago 1943) förde akustisk Delta blues norrut och elektrifierade den, vilket skapade Chicago blues. Denna migration förvandlade bokstavligen amerikansk musik, vilket ledde till blues, R&B, soul, rock ''n'' roll och så småningom hiphop.', 'Die Great Migration (1910–1970) sah, wie etwa 6 Millionen Afroamerikaner den ländlichen Süden für Städte wie Chicago, Detroit, Memphis und New York verließen. Musiker wie Muddy Waters (der 1943 die Stovall Plantation, Mississippi, in Richtung Chicago verließ) brachten den akustischen Delta Blues nach Norden und elektrifizierten ihn, wodurch Chicago Blues entstand. Diese Migration transformierte buchstäblich die amerikanische Musik und führte zu Blues, R&B, Soul, Rock ''n'' Roll und schließlich Hip-Hop.', 'Wielka Migracja (1910–1970) sprawiła, że około 6 milionów Afroamerykanów opuściło wiejskie Południe, przenosząc się do miast takich jak Chicago, Detroit, Memphis i Nowy Jork. Muzycy tacy jak Muddy Waters (który opuścił plantację Stovall w Mississippi, udając się do Chicago w 1943 roku) przynieśli akustycznego Delta bluesa na północ i zelektryfikowali go, tworząc Chicago blues. Ta migracja dosłownie przekształciła amerykańską muzykę, prowadząc do powstania bluesa, R&B, soul, rock and rolla i w końcu hip-hopu.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-26', 'multiple-choice', 'hard',
  'Who is Bobby Rush and what is his signature style?', 'Hvem er Bobby Rush og hva er hans signaturstil?', 'Vem är Bobby Rush och vad är hans signaturstil?', 'Wer ist Bobby Rush und was ist sein charakteristischer Stil?', 'Kim jest Bobby Rush i jaki jest jego charakterystyczny styl?',
  '["A Chicago pianist known for boogie-woogie","A soul-blues showman known for Southern soul blues and live shows","A harmonica player from Memphis","A Delta acoustic guitarist"]', '["En Chicago-pianist kjent for boogie-woogie","En soul-blues showman kjent for Southern soul blues og liveshow","En munnspiller fra Memphis","En Delta akustisk gitarist"]', '["En Chicago-pianist känd för boogie-woogie","En soul-blues showman känd för Southern soul blues och liveshower","En munspelare från Memphis","En Delta akustisk gitarrist"]', '["Ein Chicago-Pianist, bekannt für Boogie-Woogie","Ein Soul-Blues-Showman, bekannt für Southern Soul Blues und Liveshows","Ein Mundharmonikaspieler aus Memphis","Ein akustischer Delta-Gitarrist"]', '["Pianista z Chicago znany z boogie-woogie","Showman soul-bluesowy znany z Southern soul blues i występów na żywo","Harmonijkarz z Memphis","Akustyczny gitarzysta Delty"]',
  1,
  'Bobby Rush (born Emmett Ellis Jr. in 1933 in Homer, Louisiana) is a living blues legend with a career spanning 70+ years. Known as the ''King of the Chitlin'' Circuit,'' he won his first Grammy at age 83 for ''Porcupine Meat'' (2017). His energetic Southern soul blues shows feature comedy, dancers, and pure entertainment – performing over 200 shows a year well into his 90s.', 'Bobby Rush (født Emmett Ellis Jr. i 1933 i Homer, Louisiana) er en levende blueslegende med en karriere over 70+ år. Kjent som ''Kongen av Chitlin'' Circuit,'' vant han sin første Grammy i en alder av 83 for ''Porcupine Meat'' (2017). Hans energiske Southern soul blues-show inneholder komedie, dansere og ren underholdning – med over 200 show i året godt inn i 90-årene.', 'Bobby Rush (född Emmett Ellis Jr. 1933 i Homer, Louisiana) är en levande blueslegend med en karriär som sträcker sig över 70+ år. Känd som ''Kungen av Chitlin'' Circuit,'' vann han sin första Grammy vid 83 års ålder för ''Porcupine Meat'' (2017). Hans energiska Southern soul blues-shower innehåller komedi, dansare och ren underhållning – med över 200 shower om året långt in i 90-årsåldern.', 'Bobby Rush (geboren als Emmett Ellis Jr. 1933 in Homer, Louisiana) ist eine lebende Blues-Legende mit einer über 70-jährigen Karriere. Bekannt als ''König des Chitlin'' Circuit,'' gewann er im Alter von 83 Jahren seinen ersten Grammy für ''Porcupine Meat'' (2017). Seine energiegeladenen Southern-Soul-Blues-Shows umfassen Komödie, Tänzer und pure Unterhaltung – er gibt bis weit in seine 90er über 200 Shows im Jahr.', 'Bobby Rush (urodzony jako Emmett Ellis Jr. w 1933 roku w Homer w Luizjanie) jest żyjącą legendą bluesa z karierą trwającą ponad 70 lat. Znany jako ''Król Chitlin'' Circuit,'' zdobył swoje pierwsze Grammy w wieku 83 lat za album ''Porcupine Meat'' (2017). Jego energiczne występy w stylu Southern soul blues zawierają komedię, tancerki i czystą rozrywkę – daje ponad 200 koncertów rocznie, mając już dziewięćdziesiąt kilka lat.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-30', 'multiple-choice', 'hard',
  'Which Mavis Staples album won a Grammy in 2011?', 'Hvilket Mavis Staples-album vant en Grammy i 2011?', 'Vilket Mavis Staples-album vann en Grammy 2011?', 'Welches Mavis-Staples-Album gewann 2011 einen Grammy?', 'Który album Mavis Staples zdobył Grammy w 2011 roku?',
  '["We''ll Never Turn Back","You Are Not Alone","One True Vine","Livin'' on a High Note"]', '["We''ll Never Turn Back","You Are Not Alone","One True Vine","Livin'' on a High Note"]', '["We''ll Never Turn Back","You Are Not Alone","One True Vine","Livin'' on a High Note"]', '["We''ll Never Turn Back","You Are Not Alone","One True Vine","Livin'' on a High Note"]', '["We''ll Never Turn Back","You Are Not Alone","One True Vine","Livin'' on a High Note"]',
  1,
  '''You Are Not Alone'' (2010), produced by Wilco''s Jeff Tweedy at his Loft Studio in Chicago, won Mavis Staples her first solo Grammy for Best Americana Album in 2011. Mavis (b. 1939) began singing with The Staple Singers at age 11, performing gospel and freedom songs alongside Martin Luther King Jr. Her career bridges gospel, soul, blues, and Americana across seven decades.', '''You Are Not Alone'' (2010), produsert av Wilcos Jeff Tweedy på hans Loft Studio i Chicago, ga Mavis Staples hennes første solo-Grammy for Best Americana Album i 2011. Mavis (f. 1939) begynte å synge med The Staple Singers som 11-åring, og fremførte gospel- og frihetssanger ved siden av Martin Luther King Jr. Karrieren hennes bygger bro mellom gospel, soul, blues og Americana gjennom syv tiår.', '''You Are Not Alone'' (2010), producerat av Wilcos Jeff Tweedy på hans Loft Studio i Chicago, gav Mavis Staples hennes första solo-Grammy för Best Americana Album 2011. Mavis (f. 1939) började sjunga med The Staple Singers vid 11 års ålder, och framförde gospel- och frihetssånger tillsammans med Martin Luther King Jr. Hennes karriär bygger broar mellan gospel, soul, blues och Americana genom sju decennier.', '''You Are Not Alone'' (2010), produziert von Wilcos Jeff Tweedy in seinem Loft Studio in Chicago, brachte Mavis Staples 2011 ihren ersten Solo-Grammy für Best Americana Album ein. Mavis (geb. 1939) begann im Alter von 11 Jahren mit den Staple Singers zu singen und trug Gospel- und Freiheitslieder gemeinsam mit Martin Luther King Jr. vor. Ihre Karriere verbindet Gospel, Soul, Blues und Americana über sieben Jahrzehnte.', '''You Are Not Alone'' (2010), wyprodukowany przez Jeffa Tweedy''ego z Wilco w jego Loft Studio w Chicago, przyniósł Mavis Staples pierwsze solowe Grammy za Best Americana Album w 2011 roku. Mavis (ur. 1939) zaczęła śpiewać z The Staple Singers w wieku 11 lat, wykonując pieśni gospel i pieśni wolności u boku Martina Luthera Kinga Jr. Jej kariera łączy gospel, soul, blues i Americana przez siedem dekad.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-33', 'multiple-choice', 'hard',
  'Joe Bonamassa started performing as a child. At what age did he first open for B.B. King?', 'Joe Bonamassa begynte å opptre som barn. I hvilken alder åpnet han først for B.B. King?', 'Joe Bonamassa började uppträda som barn. Vid vilken ålder öppnade han första gången för B.B. King?', 'Joe Bonamassa trat schon als Kind auf. In welchem Alter eröffnete er zum ersten Mal für B.B. King?', 'Joe Bonamassa zaczął występować jako dziecko. W jakim wieku po raz pierwszy zagrał support dla B.B. Kinga?',
  '["8 years old","10 years old","12 years old","14 years old"]', '["8 år","10 år","12 år","14 år"]', '["8 år","10 år","12 år","14 år"]', '["8 Jahre","10 Jahre","12 Jahre","14 Jahre"]', '["8 lat","10 lat","12 lat","14 lat"]',
  2,
  'Joe Bonamassa (b. 1977) from Utica, New York opened for B.B. King at age 12 after being discovered by guitar legend Danny Gatton. He has since become the most commercially successful blues artist of the 21st century, with 25 #1 blues albums, sold-out shows at the Royal Albert Hall and Red Rocks, and a guitar collection of over 500 vintage instruments.', 'Joe Bonamassa (f. 1977) fra Utica, New York åpnet for B.B. King som 12-åring etter å ha blitt oppdaget av gitarlegenden Danny Gatton. Han har siden blitt den mest kommersielt suksessrike bluesartisten i det 21. århundre, med 25 nr. 1-bluesalbum, utsolgte show på Royal Albert Hall og Red Rocks, og en gitarsamling på over 500 vintage-instrumenter.', 'Joe Bonamassa (f. 1977) från Utica, New York öppnade för B.B. King vid 12 års ålder efter att ha upptäckts av gitarrlegenden Danny Gatton. Han har sedan dess blivit den mest kommersiellt framgångsrika bluesartisten på 2000-talet, med 25 förstaplatser på bluesalbumlistor, utsålda shower på Royal Albert Hall och Red Rocks, och en gitarrsamling på över 500 vintage-instrument.', 'Joe Bonamassa (geb. 1977) aus Utica, New York, eröffnete im Alter von 12 Jahren für B.B. King, nachdem er von der Gitarrenlegende Danny Gatton entdeckt worden war. Er ist seitdem der kommerziell erfolgreichste Bluesmusiker des 21. Jahrhunderts geworden, mit 25 Nr.-1-Blues-Alben, ausverkauften Shows in der Royal Albert Hall und bei Red Rocks sowie einer Gitarrensammlung von über 500 Vintage-Instrumenten.', 'Joe Bonamassa (ur. 1977) z Utiki w stanie Nowy Jork zagrał support dla B.B. Kinga w wieku 12 lat po tym, jak odkrył go legendarny gitarzysta Danny Gatton. Od tego czasu stał się najbardziej komercyjnie odnoszącym sukcesy artystą bluesowym XXI wieku, z 25 albumami bluesowymi na 1. miejscu list, wyprzedanymi koncertami w Royal Albert Hall i Red Rocks oraz kolekcją ponad 500 zabytkowych gitar.',
  'joe-bonamassa', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-34', 'multiple-choice', 'hard',
  'What genre fusion is Delbert McClinton known for?', 'Hvilken sjangerblanding er Delbert McClinton kjent for?', 'Vilken genreblandning är Delbert McClinton känd för?', 'Für welche Genrefusion ist Delbert McClinton bekannt?', 'Z jakiej fuzji gatunków znany jest Delbert McClinton?',
  '["Jazz and classical","Blues, country, and Americana roots","Reggae and blues","Hip-hop and blues"]', '["Jazz og klassisk","Blues, country og Americana roots","Reggae og blues","Hip-hop og blues"]', '["Jazz och klassiskt","Blues, country och Americana roots","Reggae och blues","Hip-hop och blues"]', '["Jazz und Klassik","Blues, Country und Americana Roots","Reggae und Blues","Hip-Hop und Blues"]', '["Jazz i muzyka klasyczna","Blues, country i korzenie Americana","Reggae i blues","Hip-hop i blues"]',
  1,
  'Delbert McClinton (1940–2023) was a Texas-born musician who masterfully blended blues, country, rock, and Americana into a distinctive sound. He won four Grammys, and famously taught John Lennon how to play harmonica when they shared a bill in 1962. His harmonica intro on Bruce Channel''s ''Hey! Baby'' directly inspired Lennon''s playing on ''Love Me Do.''', 'Delbert McClinton (1940–2023) var en Texas-født musiker som mesterlig blandet blues, country, rock og Americana til en distinkt lyd. Han vant fire Grammyer, og lærte berømt John Lennon å spille munnspill da de delte scene i 1962. Hans munnspillintro på Bruce Channels ''Hey! Baby'' inspirerte direkte Lennons spill på ''Love Me Do.''', 'Delbert McClinton (1940–2023) var en Texas-född musiker som mästerligt blandade blues, country, rock och Americana till ett distinkt sound. Han vann fyra Grammyar, och lärde berömt John Lennon att spela munspel när de delade scen 1962. Hans munspelsintro på Bruce Channels ''Hey! Baby'' inspirerade direkt Lennons spel på ''Love Me Do.''', 'Delbert McClinton (1940–2023) war ein in Texas geborener Musiker, der meisterhaft Blues, Country, Rock und Americana zu einem unverwechselbaren Sound verband. Er gewann vier Grammys und brachte John Lennon bekanntermaßen das Mundharmonikaspielen bei, als sie sich 1962 die Bühne teilten. Seine Mundharmonika-Einleitung bei Bruce Channels ''Hey! Baby'' inspirierte direkt Lennons Spiel auf ''Love Me Do.''', 'Delbert McClinton (1940–2023) był muzykiem urodzonym w Teksasie, który mistrzowsko łączył blues, country, rock i Americana w charakterystyczne brzmienie. Zdobył cztery nagrody Grammy i, jak głosi legenda, nauczył Johna Lennona grać na harmonijce ustnej, gdy dzielili scenę w 1962 roku. Jego wstęp na harmonijce w utworze Bruce''a Channela ''Hey! Baby'' bezpośrednio zainspirował grę Lennona w ''Love Me Do.''',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-36', 'multiple-choice', 'hard',
  'Which Muddy Waters song inspired the name ''The Rolling Stones''?', 'Hvilken Muddy Waters-låt inspirerte navnet ''The Rolling Stones''?', 'Vilken Muddy Waters-låt inspirerade namnet ''The Rolling Stones''?', 'Welcher Muddy-Waters-Song inspirierte den Namen ''The Rolling Stones''?', 'Który utwór Muddy''ego Watersa zainspirował nazwę ''The Rolling Stones''?',
  '["Hoochie Coochie Man","Rollin'' Stone","Got My Mojo Working","Mannish Boy"]', '["Hoochie Coochie Man","Rollin'' Stone","Got My Mojo Working","Mannish Boy"]', '["Hoochie Coochie Man","Rollin'' Stone","Got My Mojo Working","Mannish Boy"]', '["Hoochie Coochie Man","Rollin'' Stone","Got My Mojo Working","Mannish Boy"]', '["Hoochie Coochie Man","Rollin'' Stone","Got My Mojo Working","Mannish Boy"]',
  1,
  'The Rolling Stones took their name from Muddy Waters'' 1950 Chess Records recording ''Rollin'' Stone'' (itself inspired by a Robert Johnson lyric ''rolling stone''). When Brian Jones called Jazz News in 1962 to announce their first gig, he was asked the band''s name – he spotted a Muddy Waters LP on the floor and said ''The Rollin'' Stones.'' The band later met their hero at Chess Studios in 1964.', 'The Rolling Stones tok navnet sitt fra Muddy Waters'' Chess Records-innspilling ''Rollin'' Stone'' fra 1950 (selv inspirert av en Robert Johnson-tekst ''rolling stone''). Da Brian Jones ringte Jazz News i 1962 for å annonsere deres første spillejobb, ble han spurt om bandets navn – han så en Muddy Waters-LP på gulvet og sa ''The Rollin'' Stones.'' Bandet møtte senere sitt idol på Chess Studios i 1964.', 'The Rolling Stones tog sitt namn från Muddy Waters Chess Records-inspelning ''Rollin'' Stone'' från 1950 (i sig inspirerad av en Robert Johnson-textrad ''rolling stone''). När Brian Jones ringde Jazz News 1962 för att tillkännage deras första spelning fick han frågan om bandets namn – han fick syn på en Muddy Waters-LP på golvet och sa ''The Rollin'' Stones.'' Bandet mötte senare sin idol på Chess Studios 1964.', 'Die Rolling Stones erhielten ihren Namen von Muddy Waters'' Chess-Records-Aufnahme ''Rollin'' Stone'' von 1950 (selbst inspiriert von einer Robert-Johnson-Zeile ''rolling stone''). Als Brian Jones 1962 bei Jazz News anrief, um ihren ersten Gig anzukündigen, wurde er nach dem Namen der Band gefragt – er entdeckte eine Muddy-Waters-LP auf dem Boden und sagte ''The Rollin'' Stones.'' Die Band traf ihr Idol später 1964 in den Chess Studios.', 'The Rolling Stones wzięli swoją nazwę od nagrania Muddy''ego Watersa z 1950 roku dla Chess Records ''Rollin'' Stone'' (samo zainspirowane wersem Roberta Johnsona ''rolling stone''). Gdy Brian Jones zadzwonił do Jazz News w 1962 roku, aby ogłosić ich pierwszy koncert, zapytano go o nazwę zespołu – dostrzegł na podłodze płytę LP Muddy''ego Watersa i powiedział ''The Rollin'' Stones.'' Zespół spotkał później swojego idola w Chess Studios w 1964 roku.',
  'muddy-waters', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-37', 'multiple-choice', 'hard',
  'Which blues guitarist said ''Blues is easy to play, but hard to feel''?', 'Hvilken bluesgitarist sa ''Blues er lett å spille, men vanskelig å føle''?', 'Vilken bluesgitarrist sa ''Blues är lätt att spela, men svårt att känna''?', 'Welcher Bluesgitarrist sagte ''Blues ist leicht zu spielen, aber schwer zu fühlen''?', 'Który gitarzysta bluesowy powiedział ''Bluesa łatwo jest zagrać, ale trudno poczuć''?',
  '["Eric Clapton","Jimi Hendrix","B.B. King","Buddy Guy"]', '["Eric Clapton","Jimi Hendrix","B.B. King","Buddy Guy"]', '["Eric Clapton","Jimi Hendrix","B.B. King","Buddy Guy"]', '["Eric Clapton","Jimi Hendrix","B.B. King","Buddy Guy"]', '["Eric Clapton","Jimi Hendrix","B.B. King","Buddy Guy"]',
  1,
  'Jimi Hendrix (1942–1970) said this famous quote. Born in Seattle, he spent years on the chitlin'' circuit backing artists like Little Richard, Ike Turner, and the Isley Brothers before moving to London in 1966. His deep blues foundation – rooted in Muddy Waters, B.B. King, and Albert King – infused his psychedelic revolution with an authenticity that continues to resonate.', 'Jimi Hendrix (1942–1970) sa dette berømte sitatet. Født i Seattle, tilbrakte han år på chitlin''-kretsen som backingmusiker for artister som Little Richard, Ike Turner og Isley Brothers før han flyttet til London i 1966. Hans dype bluesgrunnlag – forankret i Muddy Waters, B.B. King og Albert King – tilførte hans psykedeliske revolusjon en autentisitet som fortsetter å resonere.', 'Jimi Hendrix (1942–1970) sa detta berömda citat. Född i Seattle, tillbringade han år på chitlin''-kretsen som backingmusiker åt artister som Little Richard, Ike Turner och Isley Brothers innan han flyttade till London 1966. Hans djupa bluesgrund – förankrad i Muddy Waters, B.B. King och Albert King – gav hans psykedeliska revolution en autenticitet som fortsätter att resonera.', 'Jimi Hendrix (1942–1970) sagte dieses berühmte Zitat. Geboren in Seattle, verbrachte er Jahre auf dem Chitlin'' Circuit als Begleitmusiker für Künstler wie Little Richard, Ike Turner und die Isley Brothers, bevor er 1966 nach London zog. Sein tiefes Blues-Fundament – verwurzelt in Muddy Waters, B.B. King und Albert King – verlieh seiner psychedelischen Revolution eine Authentizität, die bis heute nachwirkt.', 'Jimi Hendrix (1942–1970) wypowiedział ten słynny cytat. Urodzony w Seattle, spędził lata na trasach chitlin'' circuit, akompaniując takim artystom jak Little Richard, Ike Turner i Isley Brothers, zanim przeniósł się do Londynu w 1966 roku. Jego głębokie bluesowe fundamenty – zakorzenione w twórczości Muddy''ego Watersa, B.B. Kinga i Alberta Kinga – nadały jego psychodelicznej rewolucji autentyczność, która wciąż rezonuje.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-38', 'multiple-choice', 'hard',
  'Which B.B. King song did Peter Green (Fleetwood Mac) play that gave King ''the cold sweats''?', 'Hvilket B.B. King-stykke spilte Peter Green (Fleetwood Mac) som ga King ''kaldsvette''?', 'Vilket B.B. King-stycke spelade Peter Green (Fleetwood Mac) som gav King ''kalla kårar''?', 'Welchen B.B.-King-Song spielte Peter Green (Fleetwood Mac), der King ''kalten Schweiß'' verursachte?', 'Który utwór B.B. Kinga zagrał Peter Green (Fleetwood Mac), przyprawiając Kinga o ''zimne poty''?',
  '["The Thrill Is Gone","Need Your Love So Bad","Sweet Little Angel","Every Day I Have the Blues"]', '["The Thrill Is Gone","Need Your Love So Bad","Sweet Little Angel","Every Day I Have the Blues"]', '["The Thrill Is Gone","Need Your Love So Bad","Sweet Little Angel","Every Day I Have the Blues"]', '["The Thrill Is Gone","Need Your Love So Bad","Sweet Little Angel","Every Day I Have the Blues"]', '["The Thrill Is Gone","Need Your Love So Bad","Sweet Little Angel","Every Day I Have the Blues"]',
  1,
  'B.B. King said Peter Green (1946–2020) ''has the sweetest tone I ever heard; he was the only one who gave me the cold sweats.'' Green''s version of ''Need Your Love So Bad'' with Fleetwood Mac (1968) showcased a guitar tone so pure and emotional that even B.B. – the undisputed King of the Blues – was humbled. Green''s Les Paul, with its distinctive out-of-phase pickup, later passed to Gary Moore.', 'B.B. King sa at Peter Green (1946–2020) ''har den søteste tonen jeg noensinne har hørt; han var den eneste som ga meg kaldsvette.'' Greens versjon av ''Need Your Love So Bad'' med Fleetwood Mac (1968) viste en gitartone så ren og emosjonell at selv B.B. – den ubestridte blueskongen – ble ydmyket. Greens Les Paul, med sin karakteristiske fasevendete pickup, gikk senere til Gary Moore.', 'B.B. King sa att Peter Green (1946–2020) ''har den sötaste tonen jag någonsin hört; han var den enda som gav mig kalla kårar.'' Greens version av ''Need Your Love So Bad'' med Fleetwood Mac (1968) visade upp en gitarrton så ren och emotionell att till och med B.B. – den obestridda Kungen av Blues – blev ödmjukad. Greens Les Paul, med sin karakteristiska fasvända pickup, gick senare vidare till Gary Moore.', 'B.B. King sagte, Peter Green (1946–2020) ''hat den süßesten Ton, den ich je gehört habe; er war der Einzige, der mir kalten Schweiß bereitete.'' Greens Version von ''Need Your Love So Bad'' mit Fleetwood Mac (1968) zeigte einen Gitarrenton, der so rein und emotional war, dass selbst B.B. – der unangefochtene King of the Blues – gedemütigt war. Greens Les Paul mit ihrem charakteristischen phasenverschobenen Tonabnehmer ging später an Gary Moore über.', 'B.B. King powiedział, że Peter Green (1946–2020) ''ma najsłodszy ton, jaki kiedykolwiek słyszałem; był jedynym, który przyprawił mnie o zimne poty.'' Wersja ''Need Your Love So Bad'' Greena z Fleetwood Mac (1968) prezentowała brzmienie gitary tak czyste i emocjonalne, że nawet B.B. – niekwestionowany Król Bluesa – poczuł pokorę. Les Paul Greena, z charakterystycznym przesuniętym w fazie przetwornikiem, trafił później do Gary''ego Moore''a.',
  'bb-king', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-39', 'multiple-choice', 'hard',
  'Which Willie Dixon songs did Led Zeppelin cover on their debut album?', 'Hvilke Willie Dixon-låter covret Led Zeppelin på debutalbumet?', 'Vilka Willie Dixon-låtar coverade Led Zeppelin på sitt debutalbum?', 'Welche Willie-Dixon-Songs coverte Led Zeppelin auf ihrem Debütalbum?', 'Które utwory Williego Dixona coverował Led Zeppelin na swoim debiutanckim albumie?',
  '["Hoochie Coochie Man & Back Door Man","You Shook Me & I Can''t Quit You Baby","Little Red Rooster & Spoonful","Wang Dang Doodle & My Babe"]', '["Hoochie Coochie Man & Back Door Man","You Shook Me & I Can''t Quit You Baby","Little Red Rooster & Spoonful","Wang Dang Doodle & My Babe"]', '["Hoochie Coochie Man & Back Door Man","You Shook Me & I Can''t Quit You Baby","Little Red Rooster & Spoonful","Wang Dang Doodle & My Babe"]', '["Hoochie Coochie Man & Back Door Man","You Shook Me & I Can''t Quit You Baby","Little Red Rooster & Spoonful","Wang Dang Doodle & My Babe"]', '["Hoochie Coochie Man i Back Door Man","You Shook Me i I Can''t Quit You Baby","Little Red Rooster i Spoonful","Wang Dang Doodle i My Babe"]',
  1,
  'Led Zeppelin I (1969) featured two Willie Dixon compositions: ''You Shook Me'' (originally recorded by Muddy Waters, 1962) and ''I Can''t Quit You Baby'' (originally recorded by Otis Rush, 1956). Dixon was the architect of Chicago blues, writing over 500 songs. Led Zeppelin later faced plagiarism lawsuits for uncredited use of blues material, including ''Whole Lotta Love'' which borrowed from Dixon''s ''You Need Love.''', 'Led Zeppelin I (1969) inneholdt to Willie Dixon-komposisjoner: ''You Shook Me'' (opprinnelig innspilt av Muddy Waters, 1962) og ''I Can''t Quit You Baby'' (opprinnelig innspilt av Otis Rush, 1956). Dixon var arkitekten bak Chicago blues, og skrev over 500 sanger. Led Zeppelin ble senere saksøkt for ukreditert bruk av bluesmateriale, inkludert ''Whole Lotta Love'' som lånte fra Dixons ''You Need Love.''', 'Led Zeppelin I (1969) innehöll två Willie Dixon-kompositioner: ''You Shook Me'' (ursprungligen inspelad av Muddy Waters, 1962) och ''I Can''t Quit You Baby'' (ursprungligen inspelad av Otis Rush, 1956). Dixon var arkitekten bakom Chicago blues, och skrev över 500 låtar. Led Zeppelin stämdes senare för plagiat på grund av okrediterad användning av bluesmaterial, inklusive ''Whole Lotta Love'' som lånade från Dixons ''You Need Love.''', 'Led Zeppelin I (1969) enthielt zwei Willie-Dixon-Kompositionen: ''You Shook Me'' (ursprünglich 1962 von Muddy Waters aufgenommen) und ''I Can''t Quit You Baby'' (ursprünglich 1956 von Otis Rush aufgenommen). Dixon war der Architekt des Chicago Blues und schrieb über 500 Songs. Led Zeppelin sah sich später Plagiatsklagen wegen nicht kreditierter Verwendung von Blues-Material ausgesetzt, darunter ''Whole Lotta Love'', das sich bei Dixons ''You Need Love'' bediente.', 'Led Zeppelin I (1969) zawierał dwie kompozycje Williego Dixona: ''You Shook Me'' (pierwotnie nagrany przez Muddy''ego Watersa w 1962 roku) oraz ''I Can''t Quit You Baby'' (pierwotnie nagrany przez Otisa Rusha w 1956 roku). Dixon był architektem chicagowskiego bluesa, napisał ponad 500 piosenek. Led Zeppelin stanął później w obliczu procesów o plagiat za nieuznane wykorzystanie materiału bluesowego, w tym ''Whole Lotta Love'', który zapożyczył z ''You Need Love'' Dixona.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-40', 'multiple-choice', 'hard',
  'Which band''s guitarist was mentored by Lightnin'' Hopkins as a teenager?', 'Hvilken gitarist ble veiledet av Lightnin'' Hopkins som tenåring?', 'Vilken gitarrist var mentorerad av Lightnin'' Hopkins som tonåring?', 'Welcher Bandgitarrist wurde als Teenager von Lightnin'' Hopkins unterrichtet?', 'Który gitarzysta zespołu był mentorowany przez Lightnin'' Hopkinsa jako nastolatek?',
  '["Keith Richards (Rolling Stones)","Billy Gibbons (ZZ Top)","Joe Perry (Aerosmith)","Angus Young (AC/DC)"]', '["Keith Richards (Rolling Stones)","Billy Gibbons (ZZ Top)","Joe Perry (Aerosmith)","Angus Young (AC/DC)"]', '["Keith Richards (Rolling Stones)","Billy Gibbons (ZZ Top)","Joe Perry (Aerosmith)","Angus Young (AC/DC)"]', '["Keith Richards (Rolling Stones)","Billy Gibbons (ZZ Top)","Joe Perry (Aerosmith)","Angus Young (AC/DC)"]', '["Keith Richards (Rolling Stones)","Billy Gibbons (ZZ Top)","Joe Perry (Aerosmith)","Angus Young (AC/DC)"]',
  1,
  'Billy Gibbons (b. 1949) of ZZ Top was personally mentored by Houston-based Texas blues legend Lightnin'' Hopkins (1912–1982) as a teenager growing up in Houston''s Heights neighborhood. Hopkins taught him the raw, solo acoustic blues style that later fused with Gibbons'' heavy rock approach. Jimi Hendrix once called Gibbons ''America''s best young blues guitarist.''', 'Billy Gibbons (f. 1949) i ZZ Top ble personlig veiledet av Houston-baserte Texas blues-legenden Lightnin'' Hopkins (1912–1982) som tenåring i Houstons Heights-nabolag. Hopkins lærte ham den rå, solo akustiske bluesstilen som senere smeltet sammen med Gibbons'' tunge rock-tilnærming. Jimi Hendrix kalte en gang Gibbons ''Amerikas beste unge bluesgitarist.''', 'Billy Gibbons (f. 1949) i ZZ Top var personligt mentorerad av den Houston-baserade Texas blueslegenden Lightnin'' Hopkins (1912–1982) som tonåring i Houstons Heights-kvarter. Hopkins lärde honom den råa, akustiska solobluesstilen som senare smälte samman med Gibbons tunga rockstil. Jimi Hendrix kallade en gång Gibbons ''Amerikas bästa unga bluesgitarrist.''', 'Billy Gibbons (geb. 1949) von ZZ Top wurde als Teenager im Houstoner Stadtteil Heights persönlich von der in Houston ansässigen Texas-Blues-Legende Lightnin'' Hopkins (1912–1982) unterrichtet. Hopkins brachte ihm den rohen, akustischen Solo-Blues-Stil bei, der sich später mit Gibbons'' schwerem Rock-Ansatz verschmolz. Jimi Hendrix nannte Gibbons einmal ''Amerikas besten jungen Blues-Gitarristen.''', 'Billy Gibbons (ur. 1949) z ZZ Top był osobiście mentorowany przez teksańską legendę bluesa z Houston, Lightnin'' Hopkinsa (1912–1982), jako nastolatek dorastający w dzielnicy Heights w Houston. Hopkins nauczył go surowego, akustycznego solowego stylu bluesowego, który później połączył się z ciężkim podejściem rockowym Gibbonsa. Jimi Hendrix nazwał kiedyś Gibbonsa ''najlepszym młodym gitarzystą bluesowym Ameryki.''',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-41', 'multiple-choice', 'hard',
  'Jack White (The White Stripes) called which blues musician ''the most important who ever lived''?', 'Jack White (The White Stripes) kalte hvilken bluesmusiker ''den viktigste som noensinne har levd''?', 'Jack White (The White Stripes) kallade vilken bluesmusiker ''den viktigaste som någonsin levt''?', 'Welchen Bluesmusiker nannte Jack White (The White Stripes) ''den wichtigsten, der je gelebt hat''?', 'Którego muzyka bluesowego Jack White (The White Stripes) nazwał ''najważniejszym, jaki kiedykolwiek żył''?',
  '["Robert Johnson","Muddy Waters","Son House","Charley Patton"]', '["Robert Johnson","Muddy Waters","Son House","Charley Patton"]', '["Robert Johnson","Muddy Waters","Son House","Charley Patton"]', '["Robert Johnson","Muddy Waters","Son House","Charley Patton"]', '["Robert Johnson","Muddy Waters","Son House","Charley Patton"]',
  2,
  'Jack White has called Son House (1902–1988) ''the most important musician who ever lived'' and regularly covered House''s ''Death Letter'' in White Stripes concerts. Son House was a preacher-turned-bluesman whose raw, emotional Delta blues directly influenced Robert Johnson. Rediscovered in 1964 in Rochester, New York during the folk-blues revival, his performances bridged pre-war Delta blues with a new generation of listeners.', 'Jack White har kalt Son House (1902–1988) ''den viktigste musikeren som noensinne har levd'' og covret regelmessig Houses ''Death Letter'' på White Stripes-konserter. Son House var en predikant som ble bluesmann, og hans rå, emosjonelle Delta blues påvirket direkte Robert Johnson. Gjenoppdaget i 1964 i Rochester, New York under folk-blues-revivalen, bygde hans forestillinger bro mellom førkrigs Delta blues og en ny generasjon lyttere.', 'Jack White har kallat Son House (1902–1988) ''den viktigaste musikern som någonsin levt'' och coverade regelbundet Houses ''Death Letter'' på White Stripes-konserter. Son House var en predikant som blev bluesman, vars råa, emotionella Delta blues direkt påverkade Robert Johnson. Återupptäckt 1964 i Rochester, New York under folk-blues-återupplivandet, byggde hans föreställningar broar mellan förkrigstidens Delta blues och en ny generation lyssnare.', 'Jack White hat Son House (1902–1988) ''den wichtigsten Musiker, der je gelebt hat'' genannt und coverte regelmäßig Houses ''Death Letter'' bei White-Stripes-Konzerten. Son House war ein Prediger, der zum Bluesman wurde, dessen roher, emotionaler Delta Blues Robert Johnson direkt beeinflusste. 1964 in Rochester, New York, während der Folk-Blues-Wiederbelebung wiederentdeckt, schlugen seine Auftritte eine Brücke zwischen dem Vorkriegs-Delta-Blues und einer neuen Generation von Zuhörern.', 'Jack White nazwał Sona House''a (1902–1988) ''najważniejszym muzykiem, jaki kiedykolwiek żył'' i regularnie coverował utwór House''a ''Death Letter'' na koncertach The White Stripes. Son House był kaznodzieją, który został bluesmanem, a jego surowy, emocjonalny Delta blues bezpośrednio wpłynął na Roberta Johnsona. Odkryty na nowo w 1964 roku w Rochester w stanie Nowy Jork podczas odrodzenia folk-bluesa, jego występy budowały pomost między przedwojennym Delta bluesem a nowym pokoleniem słuchaczy.',
  'son-house', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-42', 'multiple-choice', 'hard',
  'Which Memphis Minnie blues song from 1929 did Led Zeppelin transform into one of rock''s heaviest recordings?', 'Hvilken Memphis Minnie blues-låt fra 1929 transformerte Led Zeppelin til en av rockens tyngste innspillinger?', 'Vilken Memphis Minnie blueslåt från 1929 förvandlade Led Zeppelin till en av rockens tyngsta inspelningar?', 'Welchen Memphis-Minnie-Bluessong von 1929 verwandelte Led Zeppelin in eine der schwersten Aufnahmen des Rock?', 'Który blues Memphis Minnie z 1929 roku Led Zeppelin przekształcił w jedno z najcięższych nagrań rocka?',
  '["Bumble Bee","When the Levee Breaks","Me and My Chauffeur Blues","Nothing in Rambling"]', '["Bumble Bee","When the Levee Breaks","Me and My Chauffeur Blues","Nothing in Rambling"]', '["Bumble Bee","When the Levee Breaks","Me and My Chauffeur Blues","Nothing in Rambling"]', '["Bumble Bee","When the Levee Breaks","Me and My Chauffeur Blues","Nothing in Rambling"]', '["Bumble Bee","When the Levee Breaks","Me and My Chauffeur Blues","Nothing in Rambling"]',
  1,
  'Led Zeppelin''s ''When the Levee Breaks'' (Led Zeppelin IV, 1971) was originally a 1929 blues song by Memphis Minnie (1897–1973) and her husband Kansas Joe McCoy, written about the Great Mississippi Flood of 1927. John Bonham''s drum sound – recorded in the stairwell of Headley Grange with a distant microphone – became one of the most sampled drum patterns in music history.', 'Led Zeppelins ''When the Levee Breaks'' (Led Zeppelin IV, 1971) var opprinnelig en blueslåt fra 1929 av Memphis Minnie (1897–1973) og hennes mann Kansas Joe McCoy, skrevet om den store Mississippi-flommen i 1927. John Bonhams trommesound – innspilt i trappeoppgangen på Headley Grange med en fjern mikrofon – ble et av de mest samplede trommepatternene i musikkhistorien.', 'Led Zeppelins ''When the Levee Breaks'' (Led Zeppelin IV, 1971) var ursprungligen en blueslåt från 1929 av Memphis Minnie (1897–1973) och hennes man Kansas Joe McCoy, skriven om den stora Mississippi-översvämningen 1927. John Bonhams trumljud – inspelat i trapphuset på Headley Grange med en avlägsen mikrofon – blev ett av de mest samplade trumpatteren i musikhistorien.', 'Led Zeppelins ''When the Levee Breaks'' (Led Zeppelin IV, 1971) war ursprünglich ein Blues-Song von 1929 von Memphis Minnie (1897–1973) und ihrem Ehemann Kansas Joe McCoy, geschrieben über die große Mississippi-Flut von 1927. John Bonhams Schlagzeugsound – aufgenommen im Treppenhaus von Headley Grange mit einem entfernten Mikrofon – wurde eines der meistgesampelten Schlagzeugmuster der Musikgeschichte.', '''When the Levee Breaks'' Led Zeppelin (Led Zeppelin IV, 1971) był pierwotnie piosenką bluesową z 1929 roku autorstwa Memphis Minnie (1897–1973) i jej męża Kansasa Joego McCoya, napisaną o Wielkiej Powodzi Mississippi w 1927 roku. Brzmienie perkusji Johna Bonhama – nagrane na klatce schodowej Headley Grange z odległym mikrofonem – stało się jednym z najczęściej samplowanych wzorów perkusyjnych w historii muzyki.',
  'memphis-minnie', 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'mc-43', 'multiple-choice', 'hard',
  'The Black Keys'' Dan Auerbach credits which blues musician as ''the beginning and the end'' for him?', 'The Black Keys'' Dan Auerbach krediterer hvilken bluesmusiker som ''begynnelsen og slutten'' for ham?', 'The Black Keys Dan Auerbach krediterar vilken bluesmusiker som ''början och slutet'' för honom?', 'Welchen Bluesmusiker nennt Dan Auerbach von The Black Keys als ''den Anfang und das Ende'' für sich?', 'Którego muzyka bluesowego Dan Auerbach z The Black Keys uważa za ''początek i koniec'' dla siebie?',
  '["Muddy Waters","R.L. Burnside","Junior Kimbrough","John Lee Hooker"]', '["Muddy Waters","R.L. Burnside","Junior Kimbrough","John Lee Hooker"]', '["Muddy Waters","R.L. Burnside","Junior Kimbrough","John Lee Hooker"]', '["Muddy Waters","R.L. Burnside","Junior Kimbrough","John Lee Hooker"]', '["Muddy Waters","R.L. Burnside","Junior Kimbrough","John Lee Hooker"]',
  2,
  'Dan Auerbach discovered Junior Kimbrough''s (1930–1998) hypnotic North Mississippi hill country blues as a teenager in Akron, Ohio, calling it ''the beginning and the end for me.'' Kimbrough ran his own juke joint near Holly Springs, Mississippi where his droning, trance-like guitar style became the blueprint for The Black Keys'' raw, lo-fi sound. The band named their studio ''Easy Eye Sound'' partly in tribute.', 'Dan Auerbach oppdaget Junior Kimbroughs (1930–1998) hypnotiske Nord-Mississippi hill country blues som tenåring i Akron, Ohio, og kalte det ''begynnelsen og slutten for meg.'' Kimbrough drev sin egen juke joint nær Holly Springs, Mississippi, der hans dronende, transe-lignende gitarstil ble malen for The Black Keys'' rå, lo-fi-lyd. Bandet kalte studioet sitt ''Easy Eye Sound'' delvis som en hyllest.', 'Dan Auerbach upptäckte Junior Kimbroughs (1930–1998) hypnotiska North Mississippi hill country blues som tonåring i Akron, Ohio, och kallade det ''början och slutet för mig.'' Kimbrough drev sitt eget juke joint nära Holly Springs, Mississippi, där hans dånande, transliknande gitarrstil blev mallen för The Black Keys råa, lo-fi-sound. Bandet döpte sin studio till ''Easy Eye Sound'' delvis som en hyllning.', 'Dan Auerbach entdeckte Junior Kimbroughs (1930–1998) hypnotischen North Mississippi Hill Country Blues als Teenager in Akron, Ohio, und nannte ihn ''den Anfang und das Ende für mich.'' Kimbrough betrieb seinen eigenen Juke Joint in der Nähe von Holly Springs, Mississippi, wo sein monotoner, tranceartiger Gitarrenstil zur Blaupause für den rohen Lo-Fi-Sound von The Black Keys wurde. Die Band nannte ihr Studio teilweise als Hommage ''Easy Eye Sound.''', 'Dan Auerbach odkrył hipnotyzujący North Mississippi hill country blues Juniora Kimbrougha (1930–1998) jako nastolatek w Akron w stanie Ohio, nazywając go ''początkiem i końcem dla mnie.'' Kimbrough prowadził własny juke joint niedaleko Holly Springs w Mississippi, gdzie jego monotonny, transowy styl gry na gitarze stał się wzorem dla surowego, lo-fi brzmienia The Black Keys. Zespół nazwał swoje studio ''Easy Eye Sound'' częściowo jako hołd dla niego.',
  NULL, 'migrated from src/data/quizQuestions.ts',
  NULL, NULL, NULL,
  NULL, NULL, NULL, NULL, NULL,
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'audio-1', 'audio-guess', 'medium',
  'Listen to this clip – who is singing?', 'Lytt til dette klippet – hvem synger?', 'Lyssna på det här klippet – vem sjunger?', 'Hör dir diesen Ausschnitt an – wer singt?', 'Posłuchaj tego fragmentu – kto śpiewa?',
  '["Muddy Waters","Howlin'' Wolf","B.B. King"]', '["Muddy Waters","Howlin'' Wolf","B.B. King"]', '["Muddy Waters","Howlin'' Wolf","B.B. King"]', '["Muddy Waters","Howlin'' Wolf","B.B. King"]', '["Muddy Waters","Howlin'' Wolf","B.B. King"]',
  1,
  'That powerful, growling voice belongs to Howlin'' Wolf performing ''Smokestack Lightning'' – one of the most distinctive vocal styles in all of blues.', 'Den kraftfulle, brummende stemmen tilhører Howlin'' Wolf som synger ''Smokestack Lightning'' – en av de mest karakteristiske vokalstilene i all blues.', 'Den kraftfulla, morrande rösten tillhör Howlin'' Wolf som sjunger ''Smokestack Lightning'' – en av de mest karakteristiska sångstilarna i all blues.', 'Diese kraftvolle, grollende Stimme gehört Howlin'' Wolf, der ''Smokestack Lightning'' singt – einer der unverwechselbarsten Gesangsstile im gesamten Blues.', 'Ten potężny, warczący głos należy do Howlin'' Wolfa wykonującego ''Smokestack Lightning'' – jeden z najbardziej charakterystycznych stylów wokalnych w całym bluesie.',
  'howlin-wolf', 'migrated from src/data/quizQuestions.ts',
  'VMUt8KdDtTY', 5, 22,
  'Listen to this 17-second blues clip. Who is singing?', 'Lytt til dette 17-sekunders bluesklippet. Hvem synger?', 'Lyssna på detta 17-sekunders bluesklipp. Vem sjunger?', 'Hör dir diesen 17-sekündigen Blues-Clip an. Wer singt?', 'Posłuchaj tego 17-sekundowego klipu bluesowego. Kto śpiewa?',
  'validated'
);
INSERT INTO quiz_questions (id, type, difficulty, question_en, question_no, question_sv, question_de, question_pl, options_en, options_no, options_sv, options_de, options_pl, correct_index, explanation_en, explanation_no, explanation_sv, explanation_de, explanation_pl, artist_slug, source_field, youtube_video_id, audio_start, audio_end, audio_hint_en, audio_hint_no, audio_hint_sv, audio_hint_de, audio_hint_pl, status) VALUES (
  'audio-2', 'audio-guess', 'medium',
  'Listen to this clip – who is singing?', 'Lytt til dette klippet – hvem synger?', 'Lyssna på det här klippet – vem sjunger?', 'Hör dir diesen Ausschnitt an – wer singt?', 'Posłuchaj tego fragmentu – kto śpiewa?',
  '["Etta James","Koko Taylor","Bessie Smith"]', '["Etta James","Koko Taylor","Bessie Smith"]', '["Etta James","Koko Taylor","Bessie Smith"]', '["Etta James","Koko Taylor","Bessie Smith"]', '["Etta James","Koko Taylor","Bessie Smith"]',
  0,
